INSERT INTO `question` (`id`, `theme_id`, `category_id`, `parent_id`, `parent_answer_id`, `question`, `multiple`, `definition`, `additional_information`, `definition_title`, `sort_order`, `level_two`) VALUES
('6c5a609b-4af4-11ee-b615-0cc47a39c2c2', '0', 'b5aa2df1-4328-11ed-af88-040300000000', NULL, NULL, 'À votre connaissance, votre structure a-t-elle pris en compte la sobriété numérique et la transition environnementale dans ses actions et projets en lien avec le numérique ? ', 0, 'Sobriété numérique : Démarche d\'amélioration continue visant à maîtriser l\'empreinte environnementale du numérique par l\'adoption d\'un usage et de pratiques raisonnées en la matière. \n\nTransition environnementale : La transition environnementale est une évolution vers un nouveau modèle économique et social, un modèle de développement durable qui renouvelle nos façons de consommer, de produire, de travailler, de vivre ensemble pour répondre aux grands enjeux environnementaux, ceux du changement climatique, de la rareté des ressources, de la perte accélérée de la biodiversité et de la multiplication des risques sanitaires environnementaux.', '', NULL, 1, 0),
('a950ed4d-4aff-11ee-b615-0cc47a39c2c2', '0', '38e51811-4329-11ed-af88-040300000000', NULL, NULL, 'Les élus de votre structure ont-ils été formés aux enjeux et bonnes pratiques en matière de sobriété numérique ?', 0, '', '', NULL, 4, 0),
('ead873c4-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', '6c5a609b-4af4-11ee-b615-0cc47a39c2c2', '01a8eb61-4af5-11ee-b615-0cc47a39c2c2', 'Votre structure a-t-elle mis en place une gouvernance pour la sobriété numérique (désignation d\'un référent, prise d\'engagements, définition d\'objectifs, mise en place d\'actions...)?', 0, '', '', NULL, 2, 0),
('ead8cae7-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead873c4-06bc-11ee-b776-0cc47a39c2c0', '0d00b3ab-06bd-11ee-b776-0cc47a39c2c0', 'Des missions liées à la sobriété numérique ont-elles été confiées au personnel? ', 0, '', '', NULL, 4, 1),
('ead8f657-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead8cae7-06bc-11ee-b776-0cc47a39c2c0', '0d0102e8-06bd-11ee-b776-0cc47a39c2c0', 'Ces personnes sont-elles à temps plein sur ces missions? ', 0, '', '', NULL, 5, 1),
('ead9205e-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead873c4-06bc-11ee-b776-0cc47a39c2c0', '0d00b3ab-06bd-11ee-b776-0cc47a39c2c0', 'Des missions liées à la sobriété numérique ont-elles été confiées aux élus?', 0, '', '', NULL, 6, 1),
('ead94a96-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead873c4-06bc-11ee-b776-0cc47a39c2c0', '0d00b3ab-06bd-11ee-b776-0cc47a39c2c0', 'Un référent sobriété numérique a-t-il été désigné?', 0, '', ' La désignation d\'un référent vise à garantir la prise en compte systématique dans le cadre du fonctionnement de la structure, ainsi que la diffusion des enjeux et bonnes pratiques de la sobriété numérique. ', NULL, 7, 1),
('ead9753f-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead873c4-06bc-11ee-b776-0cc47a39c2c0', '0d00b3ab-06bd-11ee-b776-0cc47a39c2c0', 'Un organe de pilotage et/ou groupe de travail a-t-il été mis en place sur le sujet de la sobriété numérique? ', 0, '', ' La gouvernance est un élément indispensable au bon déroulement de toute démarche d\'amélioration continue : sans vision d\'ensemble, transversale et portée par une instance de pilotage collégiale, l\'adhésion de tous au plan d\'action défini et sa mise en œuvre effective ont de fortes chances d\'être compromises. ', NULL, 8, 1),
('ead99d87-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead873c4-06bc-11ee-b776-0cc47a39c2c0', '0d00b3ab-06bd-11ee-b776-0cc47a39c2c0', 'Votre structure a-t-elle pris des engagements en matière de sobriété numérique? ', 0, '', '', NULL, 9, 1),
('ead9ca87-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead99d87-06bc-11ee-b776-0cc47a39c2c0', '0d02bf0b-06bd-11ee-b776-0cc47a39c2c0', 'Les engagements pris par votre structure ont-ils été rendus publics?', 0, '', ' Le fait de rendre publics les engagements pris fait appel au devoir d\'exemplarité. Cela vise à encourager votre structure à concrétiser et tenir ses engagements.', NULL, 10, 1),
('ead9ef35-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead873c4-06bc-11ee-b776-0cc47a39c2c0', '0d00b3ab-06bd-11ee-b776-0cc47a39c2c0', 'Votre structure a-t-elle engagé des actions ou fixé des objectifs en matière de sobriété numérique? ', 0, '', '', NULL, 11, 1),
('eada1203-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead9ef35-06bc-11ee-b776-0cc47a39c2c0', '0d03888c-06bd-11ee-b776-0cc47a39c2c0', 'Les actions engagées et/ou objectifs fixés par votre structure ont-ils été formalisés sous forme d\'un plan d\'actions?', 0, '', ' Afin de mener une démarche d\'amélioration continue cohérente et efficace, l\'élaboration d\'un plan d\'action est une étape incontournable. ', NULL, 12, 1),
('eada3460-06bc-11ee-b776-0cc47a39c2c0', '0', 'b5aa2df1-4328-11ed-af88-040300000000', 'ead873c4-06bc-11ee-b776-0cc47a39c2c0', '0d00b3ab-06bd-11ee-b776-0cc47a39c2c0', 'Avez-vous alloué une part du budget de votre structure à la mise en oeuvre d\'une démarche de sobriété numérique? ', 0, '', '', NULL, 13, 1),
('eada5694-06bc-11ee-b776-0cc47a39c2c0', '0', '38e51811-4329-11ed-af88-040300000000', NULL, NULL, 'Des actions de sensibilisation sont-elles menées auprès du personnel sur les enjeux et bonnes pratiques en matière de sobriété numérique? ', 0, '', ' La sensibilisation peut être assurée par le relai d\'informations (celles produites par l\'ADEME ou encore l\'INR), l\'organisation d\'évènements thématiques (par exemple la Fresque du numérique ou du climat ou le World Clean Up Day). Elle vise à alerter et apporter un premier niveau de connaissances sur le sujet. \nUne bonne compréhension des enjeux et bonnes pratiques de la sobriété numérique est un préalable indispensable à la mise en oeuvre du plan d\'action défini. Elle est le gage d\'une meilleure adhésion à la démarche de chacune des parties prenantes. \nLa diversification des supports de sensibilisation assure une diffusion optimale des enjeux et bonnes pratiques de la sobriété numérique auprès de différents utilisateurs. ', NULL, 1, 0),
('eada8fd0-06bc-11ee-b776-0cc47a39c2c0', '0', '38e51811-4329-11ed-af88-040300000000', NULL, NULL, 'Le personnel de votre structure a-t-il été formé aux enjeux et bonnes pratiques en matière de sobriété numérique? ', 0, '', ' La formation vient en complément de la sensibilisation afin d\'apporter les compétences nécessaires à la bonne mise en oeuvre du plan d\'actions (par exemple formation aux achats responsables pour les acheteurs publics, aux enjeux et bonnes pratiques de la sobriété numérique pour le référent ou encore à l\'écoconception pour le service informatique). \nLa formation des responsables et/ou agents et autres personnes les plus concernés est l\'assurance que les enjeux et bonnes pratiques de la sobriété numérique soient bien systématiquement pris en compte et intégrés aux divers projets qu\'ils mènent à bien. Cela contribue par ailleurs à la sensibilisation des équipes dans lesquelles ils évoluent ou avec lesquelles ils collaborent, et donc à l\'acculturation de l\'ensemble de la structure. ', NULL, 2, 0),
('eadacc92-06bc-11ee-b776-0cc47a39c2c0', '0', '38e51811-4329-11ed-af88-040300000000', NULL, NULL, 'Des actions de sensibilisation sont-elles menées auprès des élus sur les enjeux et bonnes pratiques en matière de sobriété numérique? ', 0, '', '', NULL, 3, 0),
('eadb0117-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', NULL, NULL, 'Votre structure a-t-elle recours à la location de matériels numériques? ', 0, '', ' Selon le Guide des achats numériques responsables de la Direction des Achats de l\'État (DAE) : La location est une alternative à l\'achat des équipements numériques. Cette pratique permet à l\'organisation d\'ajuster son parc au besoin de chaque utilisateur et de faire face à des urgences ou à des besoins ponctuels. Cette approche est un des axes forts de l\'économie circulaire : «l\'économie de la fonctionnalité» c\'est à dire acheter l\'usage plutôt que le bien.\r\nPour autant, son impact bénéfique reste conditionné au fait que le matériel loué soit réintroduit dans un cycle de vie prolongé par l\'opérateur.', NULL, 1, 0),
('eadb3a87-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', NULL, NULL, 'Votre structure a-t-elle pris des mesures permettant de favoriser la sobriété numérique dans les achats et locations d\'équipements et services numériques telles que l\'ajout de clauses contractuelles, une prise en compte des écolabels, des indices de réparabilité, d\'éco-conception, d\'achat ou de location d\'équipements issus du réemploi ou de la réutilisation ?', 0, 'Écolabel : Le terme « écolabel » est réservé aux labels environnementaux qui répondent à la norme ISO 14024, c\'est-à-dire respectant des exigences très précises prenant en compte les impacts environnementaux des produits tout au long de leur cycle de vie.\r\nLes produits sont certifiés par un organisme indépendant, garantissant la conformité du produit aux critères d\'un référentiel, préalablement élaboré en commun par des professionnels, des associations de consommateurs et de protection de l\'environnement et les pouvoirs publics. \r\n\r\nIndice de réparabilité : L\'indice de réparabilité est une information transmise à l\'acheteur d\'un équipement électroménagers et électroniques sur la capacité à réparer le produit acheté. Les critères et les modalités de calcul de l\'indice de réparabilité incluent notamment la démontabilité du produit, la disponibilité des conseils d\'utilisation et d\'entretien, encore la disponibilité et le prix des pièces détachées nécessaires au bon fonctionnement du produit. Prévu par la loi anti-gaspillage et l\'article L. 541-9-2 du code de l\'environnement, l\'indice de réparabilité est obligatoire depuis le 1er janvier 2021. Il concerne 5 catégories d\'équipements électroménagers et électroniques, notamment les ordinateurs et les smartphones.\r\n\r\nÉcoconception : L\'éco-conception est un standard pour réduire les impacts environnementaux d\'un produit ou d\'un service défini par la norme ISO 14062 qui intègre des contraintes environnementales dans la conception de produits et services selon une approche globale et multicritères. \r\n\r\nRéemploi : Toute opération par laquelle des substances, matières ou produits qui ne sont pas des déchets sont utilisés de nouveau pour un usage identique à celui pour lequel ils avaient été conçus. \r\n\r\nRéutilisation : Toute opération par laquelle des substances, matières ou produits qui sont devenus des déchets sont utilisés de nouveau.', '', NULL, 2, 0),
('eadb8410-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadb3a87-06bc-11ee-b776-0cc47a39c2c0', '0d065fb8-06bd-11ee-b776-0cc47a39c2c0', 'Votre structure a-t-elle recours au réemploi interne de matériels numériques? ', 0, 'Le réemploi interne de matériels numériques consistent à les réaffecter à d\'autres utilisateurs aux besoins desquels ils peuvent encore répondre. Par exemple en réaffectant l\'ordinateur utilisé par le service communication à un autre poste nécessitant un appareil moins exigeant en terme de performance (pour réaliser des tâches bureautiques simples par exemple).', ' Le meilleur outil numérique est celui que l\'on n\'achète pas car la phase de fabrication est la plus impactante pour l\'environnement (épuisement des ressources abiotiques, consommation en eau et énergie...). Ainsi, il est préférable, dans la mesure du possible, de privilégier le réemploi de matériel existant ou l\'acquisition de matériel reconditionné. ', NULL, 3, 1),
('eadbba62-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadb3a87-06bc-11ee-b776-0cc47a39c2c0', '0d065fb8-06bd-11ee-b776-0cc47a39c2c0', 'Votre structure a-t-elle recours aux filières externes du reconditionnement, du réemploi et/ou de la réutilisation en matière d\'achats numériques?', 0, 'Selon l\'article R122-4 du code de la consommation, Un produit ou une pièce détachée d\'occasion, au sens de l\'article L. 321-1 du code de commerce, peut être qualifié de \'\' produit reconditionné \'\' ou être accompagné du terme \'\' reconditionné \'\', dès lors que les conditions suivantes sont réunies :\r\n\r\n1° Le produit ou la pièce détachée a subi des tests portant sur toutes ses fonctionnalités afin d\'établir qu\'il répond aux obligations légales de sécurité et à l\'usage auquel le consommateur peut légitimement s\'attendre ;\r\n\r\n2° S\'il y avait lieu, le produit ou la pièce détachée a subi une ou plusieurs interventions afin de lui restituer ses fonctionnalités. Cette intervention inclut la suppression de toutes les données enregistrées ou conservées en lien avec un précédent usage ou un précédent utilisateur, avant que le produit ou la pièce ne change de propriétaire. ', '', NULL, 4, 1),
('eadbf343-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadb3a87-06bc-11ee-b776-0cc47a39c2c0', '0d065fb8-06bd-11ee-b776-0cc47a39c2c0', 'Des clauses environnementales sont-elles inclues dans les appels d\'offre et contrats conclus hors marché pour l\'achats d\'équipements numériques? ', 0, '', ' Il est important de demander des garanties et engagements des candidats aux marchés publics portant sur le numérique (achat de matériels, solutions logicielles, création/refonte d\'un site internet, d\'une application...) compte tenu de la part importante de la conception/fabrication dans l\'impact environnemental d\'un produit numérique. Cela est d\'autant plus important pour les collectivités territoriales qui commencent à avoir des obligations en la matière (cf. la loi AGEC et son décret d\'application du 9 mars et le projet de loi pour réduire l\'empreinte environnementale du numérique en France). \r\nCela s\'inscrit enfin dans les objectifs du Plan National des Achats Responsables (PNAD) 2022-2025 et notamment celui visant à ce que, d\'ici 2025, 100% des contrats de la commande publique notifiés au cours de l\'année comprennent au moins une considération environnementale. ', NULL, 5, 1),
('eadc2bc8-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadb3a87-06bc-11ee-b776-0cc47a39c2c0', '0d065fb8-06bd-11ee-b776-0cc47a39c2c0', 'Tenez-vous compte des écolabels et autres référentiels dans le cadre de vos achats numériques (Energie Star, 80 Plus, EPEAT, Blue Angel...)? ', 0, '', ' Les écolabels sont le gage de faire l\'acquisition d\'équipements numériques conçus avec des matériaux et substances moins impactantes pour l\'environnement, pour durer et consommer le moins d\'énergie possible durant leur fonctionnement, ou encore dont la fin de vie et notamment le recyclage est optimisé dès leur fabrication. ', NULL, 6, 1),
('eadc66b4-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadb3a87-06bc-11ee-b776-0cc47a39c2c0', '0d065fb8-06bd-11ee-b776-0cc47a39c2c0', 'Tenez-vous compte de l\'indice de réparabilité dans le cadre de vos achats pour les outils numériques qui en disposent? ', 0, '', ' Dans une optique d\'allongement de la durée de vie des outils numériques, il est préférable d\'opter pour ceux facilement réparables (conception simplifiant le démontage, disponibilité de pièces détachées...), dans l\'attente de l\'apparition de l\'indice de durabilité. ', NULL, 7, 1),
('eadc9d71-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadb3a87-06bc-11ee-b776-0cc47a39c2c0', '0d065fb8-06bd-11ee-b776-0cc47a39c2c0', 'Votre structure dispose-t-elle d\'une politique d\'achat et de renouvellement des outils numériques définie?', 0, '', ' La mise en place d\'une politique d\'achats sera bénéfique tant pour l\'environnement que pour la rationalisation des coûts qui en découlera. Cela est aussi un facteur d\'amélioration des process internes par la documentation. ', NULL, 8, 1),
('eadcd379-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', NULL, NULL, 'Votre structure a-t-elle pris des mesures permettant de favoriser la sobriété numérique dans les achats pour l\'impression telles que le choix du papier, de l\'encre et des toners ?', 0, '', '', NULL, 9, 0),
('eade5b21-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadcd379-06bc-11ee-b776-0cc47a39c2c0', '0d092c84-06bd-11ee-b776-0cc47a39c2c0', 'Tenez-vous compte des écolabels dans le cadre de vos achats de papiers (FSC, PEFC, Blue Angel......)?', 0, '', ' En moyenne, un français imprime 20 pages par jour, ce qui représente, notamment, par personne et par an : \n- 6 600 pages imprimées ; \n- 1 arbre utilisé ; \n- 12 500 litres d\'eau consommés. \nOr, derrière ces chiffres, il faut tenir compte du fait que : \n- les e-mails représentent 10 à 38% du volume d\'impression ; \n- 16% des impressions ne sont jamais lues et 65% pourraient être lues sur un écran ; \n- ¼ des impressions sont jetées dans les 5 minutes suivant l\'impression.\nIl est donc nécessaire d\'agir pour réduire l\'impact des impressions. ', NULL, 10, 1),
('eade9913-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadcd379-06bc-11ee-b776-0cc47a39c2c0', '0d092c84-06bd-11ee-b776-0cc47a39c2c0', 'Utilisez-vous du papier recyclé pour vos impressions?', 0, '', '', NULL, 11, 1),
('eadec861-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', 'eadcd379-06bc-11ee-b776-0cc47a39c2c0', '0d092c84-06bd-11ee-b776-0cc47a39c2c0', 'Avez-vous adopté des pratiques d\'achat en matière de toner et cartouches d\'encre sobres (recharge, achat de toner/cartouches recyclés...)? ', 0, '', '', NULL, 12, 1),
('eadefc43-06bc-11ee-b776-0cc47a39c2c0', '0', 'e4a990cd-4329-11ed-af88-040300000000', NULL, NULL, 'Faîtes-vous appel à des fournisseurs d\'énergie dite « verte »/renouvelable? ', 0, 'Énergies primaires : L\'énergie primaire est celle qui sert notamment à fabriquer l\'électricité que nous consommons, appelée quant à elle « énergie finale » (nucléaire, hydraulique, solaire, gaz, pétrole, charbon...). \r\nÉnergies renouvelables/fossiles : Une énergie est dite renouvelable lorsqu\'elle provient de sources que la nature renouvelle en permanence, par opposition à une énergie non renouvelable dont les stocks s\'épuisent, ce qui est le cas des énergies fossiles. ', ' Les énergies primaires dites fossiles utilisées pour la production de l\'électricité nécessaire au fonctionnement du parc numérique ont un impact environnemental supérieur aux énergies dites renouvelables. \r\nL\'achat de ce type d\'énergie consiste à l\'obtention d\'un certificat attestant qu\'une quantité d\'énergie équivalente à la consommation du client produite à partir de sources d\'énergies renouvelables a été injectée dans le réseau de distribution. Il n\'est en effet pas possible de déterminer la nature de l\'énergie effectivement consommée à la prise électrique : toutes les productions se confondent une fois qu\'elles ont rejoint le réseau de distribution. \r\nLe but est d\'aider au développement des filières renouvelables afin que la part de production qui en est issue augmente, entrainant une baisse des impacts environnementaux liés aux énergies fossiles. ', NULL, 13, 0),
('eadf40b1-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'Disposez-vous d\'un inventaire du parc numérique de votre structure (postes informatiques et écrans, téléphones, tablettes, supports de sauvegardes amovibles, vidéoprojecteurs...)? ', 0, '', ' Une gestion optimale du parc numérique implique d\'en connaître la composition de manière à affecter au mieux les ressources existantes tout en limitant les acquisitions au strict nécessaire, avec tous les impacts environnementaux que cela permet d\'éviter. ', NULL, 1, 0),
('eadf7764-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eadf40b1-06bc-11ee-b776-0cc47a39c2c0', '0d0b296c-06bd-11ee-b776-0cc47a39c2c0', 'Avez-vous documenté l\'architecture de votre système d\'information (serveurs et autres matériels informatiques, infrastructures, applicatif, etc.)? ', 0, 'Un système d\'information (SI) est un ensemble des moyens humains et matériels (terminaux et infrastructures numériques, solutions applicatives, etc.) ayant pour finalité d\'élaborer, traiter, stocker, acheminer, présenter ou détruire l\'information.', ' La cartographie est un outil essentiel à la maîtrise du système d\'information. Elle permet d\'avoir connaissance de l\'ensemble des composants du SI et d\'obtenir une meilleure lisibilité de celui-ci en le présentant sous différentes vues. Au-delà de la sécurité, c\'est donc un élément indispensable à la rationalisation du SI en vue de réduire son impact environnemental. ', NULL, 2, 1),
('eadfd1c0-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eadf40b1-06bc-11ee-b776-0cc47a39c2c0', '0d0b296c-06bd-11ee-b776-0cc47a39c2c0', 'L\'architecture de votre système d\'information est-elle optimisée par rapport aux besoins de votre structure? ', 0, '', ' La rationalisation du système d\'information (SI) permet d\'éviter des coûts et impacts environnementaux dispensables. ', NULL, 3, 1),
('eae0041e-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eadf40b1-06bc-11ee-b776-0cc47a39c2c0', '0d0b296c-06bd-11ee-b776-0cc47a39c2c0', 'Quelle est la durée de vie moyenne des postes informatiques de votre structure? ', 0, '', '', NULL, 4, 1),
('eae03ede-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eadf40b1-06bc-11ee-b776-0cc47a39c2c0', '0d0b296c-06bd-11ee-b776-0cc47a39c2c0', 'Quelle est la durée de vie moyenne des copieurs/imprimantes de votre structure? ', 0, '', '', NULL, 5, 1),
('eae07ac9-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eadf40b1-06bc-11ee-b776-0cc47a39c2c0', '0d0b296c-06bd-11ee-b776-0cc47a39c2c0', 'Quelle est la durée de vie moyenne des téléphones de votre structure?', 0, '', '', NULL, 6, 1),
('eae0b739-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'Assurez-vous la traçabilité des attributions et besoins en outils informatiques en interne? ', 0, '', '', NULL, 7, 0),
('eae0efce-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae0b739-06bc-11ee-b776-0cc47a39c2c0', '0d0d8749-06bd-11ee-b776-0cc47a39c2c0', 'Connaissez-vous le taux moyen d\'équipement numérique/utilisateur de votre structure? ', 0, '', 'Le taux moyen d\'équipement par utilisateur peut être pertinent en prenant en compte dans le calcul, soit uniquement les agents utilisant des équipements numériques dans le cadre de leurs missions, soit l\'ensemble des agents de la structure. Si possible réaliser les deux calculs.', NULL, 8, 1),
('eae128ef-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae0b739-06bc-11ee-b776-0cc47a39c2c0', '0d0d8749-06bd-11ee-b776-0cc47a39c2c0', 'Quels sont le nombre et la taille moyenne des écrans mis à disposition des utilisateurs ?', 0, '', ' La consommation d\'énergie et de matières d\'un écran augmente avec le carré de la diagonale. Plus un écran est grand, plus il consomme. Il convient donc de limiter les écrans supplémentaires, ainsi que leur taille. \r\nPour les ordinateurs portables, la taille de l\'écran impacte l\'autonomie de la batterie. En effet, les deux tiers de l\'énergie d\'un ordinateur son imputables à l\'écran.', NULL, 9, 1),
('eae2025d-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae0b739-06bc-11ee-b776-0cc47a39c2c0', '0d0d8749-06bd-11ee-b776-0cc47a39c2c0', 'Combien de téléphones professionnels (fixes et mobiles) sont-ils mis à disposition des utilisateurs de votre structure et de quels types (téléphones simples, reconditionnés, en réemploi, smartphone...)? ', 0, '', ' Selon L\'Institut du Numérique Responsable (INR) : Bien que les téléphones fixes aient une durée de vie longue et que leur empreinte environnementale soit faible comparée à celle des autres équipements du système d\'information, ils sont souvent plus nombreux que les utilisateurs. Par ailleurs, les téléphones fixes sont de moins en moins utilisés car ils sont souvent redondants avec les mobiles (notamment depuis l\'apparition des forfaits mobiles illimités).', NULL, 12, 1),
('eae246b3-06bc-11ee-b776-0cc47a39c2c0', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'L\'utilisation des outils professionnels à des fins personnelles et/ou l\'utilisation d\'outils personnels à des fins professionnelles est-elle autorisée?', 0, 'L\'acronyme \"BYOD\" signifie \"Bring Your Own Device\" (en français : \"Apportez Votre Equipement Personnel de Communication\" ou AVEC). Cela désigne l\'usage d\'équipements informatiques dans un contexte professionnel.', ' La mutualisation des usages permet la réduction du taux d\'équipement et impacts liés à la démultiplication des outils numériques. \nConcernant par exemple les téléphones et ordinateurs portables, les impacts environnementaux liés à ces derniers sont nombreux touts au long de son cycle de vie, aussi est-il préférable de ne pas faire doublon avec un terminal professionnel et un autre personnel lorsque cela est possible. L\'ANSSI (Agence Nationale de Sécurité des Systèmes d\'Information) indique que cette pratique du BYOD est à proscrire (se référer à son guide du nomadisme de 2018). La CNIL (Commission Nationale de l\'informatique et des libertés est plus mesurée (avec les bonnes mesures de sécurité la pratique n\'est pas systématiquement à éviter).\n\nDans tous cas, s\'assurer de prendre en compte les composantes de cybersécurité avant toute action en la matière.', NULL, 14, 0),
('eae2877c-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'Avez-vous mis en place des consignes et pratiques de nature à allonger la durée de vie de vos équipements numériques (favoriser la réparation avant le remplacement, dissocier le remplacement des équipements selon les besoins, maintenance...)?', 0, '', 'La mise en place d\'un document centralisant ces éléments d\'information permettra une meilleure gestion du parc numérique. ', NULL, 1, 0),
('eae2c4d3-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', '0d107c20-06bd-11ee-b776-0cc47a39c2c0', 'Mettez-vous à disposition des protections pour les équipements numériques fournis (sacoche, coque...)?', 0, '', '', NULL, 2, 1),
('eae300f3-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', '0d107c20-06bd-11ee-b776-0cc47a39c2c0', 'Régulez-vous les attributions d\'équipements numériques en fonction des besoins réels des utilisateurs?', 0, '', '', NULL, 3, 1),
('eae33bb4-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', '0d107c20-06bd-11ee-b776-0cc47a39c2c0', 'Quelle est la durée de dotation moyenne pour les principaux équipements mis à disposition des utilisateurs (ordinateurs fixes ou mobiles, écrans et autres accessoires, téléphones mobiles et tablettes)? ', 0, '', '', NULL, 4, 1),
('eae37420-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', '0d107c20-06bd-11ee-b776-0cc47a39c2c0', 'La configuration des équipements numériques est-elle adaptée aux différents profils utilisateur? ', 0, '', '', NULL, 4, 1),
('eae3aeb4-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', '0d107c20-06bd-11ee-b776-0cc47a39c2c0', 'Le renouvellement des unités centrales est-il dissocié de celui des écrans et autres accessoires? ', 0, '', ' Selon l\'Institut du Numérique Responsable (INR) : La durée de vie des écrans est souvent 2 à 3 fois plus longue que celle des desktops/laptops et les autres périphériques (station d\'accueil, clavier, souris, chargeurs, sacoches, etc.) sont quasiment inusables. \r\nCette bonne pratique réduit considérablement les impacts environnementaux – notamment ceux associés à la fabrication et à la fin de vie des équipements - tout en faisant faire d\'importantes économies à l\'entreprise. Et l\'utilisateur conserve son environnement habituel.', NULL, 5, 1),
('eae3ecd0-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', '0d107c20-06bd-11ee-b776-0cc47a39c2c0', 'La mise à niveau notamment par l\'ajout ou le remplacement de composants est-elle privilégiée au renouvellement des outils numériques? ', 0, '', '', NULL, 6, 1),
('eae42705-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae3ecd0-06bc-11ee-b776-0cc47a39c2c0', '0d144cb7-06bd-11ee-b776-0cc47a39c2c0', 'Des composants disponibles en interne sont-ils utilisés pour la mise à niveau des équipements numériques (issus d\'autres équipements en fin de vie par exemple)? ', 0, '', '', NULL, 7, 1),
('eae46319-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', '0d107c20-06bd-11ee-b776-0cc47a39c2c0', 'Réparez-vous les équipements numériques en cas de panne/casse?', 0, '', ' D\'après le rapport d\'information Pour une transition numérique écologique de la mission d\'information sur l\'empreinte environnementale du numérique remis au Sénat : La fabrication et la distribution (la « phase amont ») de ces terminaux utilisés en France engendrent 86 % de leurs émissions totales et sont donc responsables de 70 % de l\'empreinte carbone totale du numérique en France.\r\nAinsi, plus la durée de vie des équipements numériques est allongée, moins il est nécessaire de les renouveler, ce qui réduit mécaniquement les impacts de la phase amont décrits ci-avant.', NULL, 8, 1),
('eae4a1db-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', '0d107c20-06bd-11ee-b776-0cc47a39c2c0', 'La maintenance informatique (matériel et logiciels) est-elle assurée de façon régulière? ', 0, '', '', NULL, 9, 1),
('eae4daaa-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'Utilisez-vous des solutions logicielles et systèmes d\'exploitation libres?', 0, '', ' Le libre, par son mode de fonctionnement basé sur une contribution communautaire, est plus vertueux en ce qu\'il favorise moins l\'obsolescence logicielle que les solutions logicielles et systèmes d\'exploitation reposant sur un écosystème propriétaire et fermé. \r\nPar exemple, le système d\'exploitation Linux est reconnu pour permettre le prolongement de la durée de vie de poste informatique ancien.', NULL, 10, 0),
('eae51626-06bc-11ee-b776-0cc47a39c2c0', 'b11106a0-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'Qu\'advient-il du matériel encore fonctionnel remplacé?', 0, '', ' L\'allongement de la durée de vie des équipements numériques est la priorité compte tenu de l\'impact de leur fabrication. Opter pour le réemploi du matériel numérique encore fonctionnel permet d\'y contribuer en lui offrant une nouvelle vie. ', NULL, 11, 0),
('eae552de-06bc-11ee-b776-0cc47a39c2c0', 'b111b80e-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'Avez-vous mis en place des consignes et pratiques de nature à réduire la consommation d\'énergie de votre parc informatique (mise en veille, extinction des équipements, paramétrage de la luminosité, suivi des consommations...)? ', 0, '', '', NULL, 1, 0),
('eae58bfd-06bc-11ee-b776-0cc47a39c2c0', 'b111b80e-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae552de-06bc-11ee-b776-0cc47a39c2c0', '0d16bb01-06bd-11ee-b776-0cc47a39c2c0', 'Les équipements numériques sont-ils paramétrés de manière à réduire leur consommation d\'énergie (mode économie d\'énergie par défaut, suppression d\'applications énergivores, paramétrage par défaut de la luminosité, etc.)?', 0, '', '', NULL, 2, 1),
('eae5ca98-06bc-11ee-b776-0cc47a39c2c0', 'b111b80e-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae552de-06bc-11ee-b776-0cc47a39c2c0', '0d16bb01-06bd-11ee-b776-0cc47a39c2c0', 'Avez-vous mis en place une politique d\'économie d\'énergie de votre système d\'information (SI)? ', 0, '', ' La centralisation des paramétrages et bonnes pratiques diffusées favorisant les économies d\'énergie en un document unique permet d\'en assurer l\'application systématique et ainsi la pleine effectivité. ', NULL, 3, 1),
('eae6072c-06bc-11ee-b776-0cc47a39c2c0', 'b111b80e-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae552de-06bc-11ee-b776-0cc47a39c2c0', '0d16bb01-06bd-11ee-b776-0cc47a39c2c0', 'Avez-vous mis en place des outils de mesure de la consommation d\'énergie de votre parc informatique? ', 0, '', ' Si la consommation d\'énergie finale (électricité principalement) n\'est pas considérée comme une donnée déterminante de l\'impact environnemental du numérique, elle reste toutefois utile à étudier pour déceler des axes d\'amélioration. ', NULL, 4, 1),
('eae642ee-06bc-11ee-b776-0cc47a39c2c0', 'b111b80e-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae6072c-06bc-11ee-b776-0cc47a39c2c0', '0d18255f-06bd-11ee-b776-0cc47a39c2c0', 'Utilisez-vous un logiciel de power management? ', 0, 'Solution logicielle ayant pour objet d\'améliorer et d\'optimiser l\'efficacité énergétique d\'un parc numérique, principalement par la surveillance et le contrôle des équipements le composant. ', '', NULL, 5, 1),
('eae67ca7-06bc-11ee-b776-0cc47a39c2c0', 'b111b80e-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae6072c-06bc-11ee-b776-0cc47a39c2c0', '0d18255f-06bd-11ee-b776-0cc47a39c2c0', 'Connaissez-vous la part du système d\'information (SI) dans la consommation énergétique totale de votre structure? ', 0, '', '', NULL, 6, 1),
('eae6b4b3-06bc-11ee-b776-0cc47a39c2c0', 'b111b80e-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae552de-06bc-11ee-b776-0cc47a39c2c0', '0d16bb01-06bd-11ee-b776-0cc47a39c2c0', 'Avez-vous mis en place des outils de mesure de l\'impact environnemental de votre parc numérique?', 0, '', ' Il est primordial de mesurer l\'impact environnemental du système d\'information (SI) afin de pouvoir quantifier et suivre les améliorations résultant de l\'ensemble des actions mises en place. Cela permettra également, lorsque cette pratique sera généralisée, de réaliser des études comparatives entre les structures. ', NULL, 7, 1),
('eae6f0c0-06bc-11ee-b776-0cc47a39c2c0', 'b111b80e-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'Avez-vous mis en place des paramétrages favorisant la sobriété numérique en matière d\'impression de documents (impression en noir et blanc, recto/verso, protégée...)? ', 0, '', '', NULL, 8, 0),
('eae72d87-06bc-11ee-b776-0cc47a39c2c0', 'b112172d-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', NULL, NULL, 'Connaissez-vous les obligations de votre structure en matière de traitement des DEEE? ', 0, 'Les DEEE ou D3E sont les déchets d\'équipements électriques et électroniques (EEE) en fin de vie. Ils sont considérés par la réglementation environnementale en vigueur comme étant des déchets dangereux car ils contiennent des substances réglementées. Le code de l\'environnement définit les équipements électriques et électroniques comme étant des équipements « fonctionnant grâce à des courants électriques ou à des champs électromagnétiques, ainsi que les équipements de production, de transfert et de mesure de ces courants et champs, conçus pour être utilisés à une tension ne dépassant pas 1 000 volts en courant alternatif et 1 500 volts en courant continu. »\r\nIls contiennent par ailleurs des ressources qui peuvent être réutilisées ou recyclées. ', ' Une mauvaise gestion des EEE encore fonctionnels et DEEE est source de nombreux impacts négatifs, notamment : \r\n- Perte de matériaux réutilisables ; \r\n- Pollution de l\'air et des sols ; \r\n- Favorisation des trafics mondiaux liés aux DEEE ; \r\n- Pollution et impacts sociaux au sein des tiers pays où sont envoyés les DEEE pour traitement...', NULL, 1, 0),
('eae791b1-06bc-11ee-b776-0cc47a39c2c0', 'b112172d-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae72d87-06bc-11ee-b776-0cc47a39c2c0', '0d1a4a0c-06bd-11ee-b776-0cc47a39c2c0', 'Une politique de gestion des DEEE est-elle en place (postes informatiques, téléphones, imprimantes/scanners, cartouches d\'encre et toner...)? ', 0, '', '', NULL, 2, 0),
('eae7cc9e-06bc-11ee-b776-0cc47a39c2c0', 'b112172d-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae791b1-06bc-11ee-b776-0cc47a39c2c0', '0d1abd7a-06bd-11ee-b776-0cc47a39c2c0', 'Pourriez-vous estimer le volume de vos DEEE sur une année? ', 0, '', '', NULL, 3, 1),
('eae80242-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', NULL, NULL, 'Selon quelle modalité les outils numériques sont-ils reliés au réseau internet?', 0, '', ' Plusieurs études ont démontré que les réseaux mobiles (2G/3G4G/5G) présentent un impact environnemental largement supérieur aux autres (filaire et Wi-Fi). Voir notamment la note de synthèse de l\'étude corédigée par l\'Arcep et l\'ADEME de janvier 2022 (Évaluation de l\'impact environnemental du numérique en France et analyse prospective) : Par ailleurs, les réseaux fixes concentrent la majorité des impacts (entre 75 et 90 % des impacts suivant l\'indicateur). Mais, rapporté à la quantité de Go consommée sur chaque réseau, l\'impact environnemental des réseaux fixes devient inférieur à celui des réseaux mobiles. Par Go consommé, les réseaux mobiles ont près de trois fois plus d\'impact que les réseaux fixes pour l\'ensemble des indicateurs environnementaux étudiés.  ', NULL, 1, 0),
('eae84289-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', NULL, NULL, 'Une politique de gestion des données numériques (suppression des doublons, mutualisation des données, durée de conservation limitée, archivage intermédiaire et définitif, système d\'archivage électronique (SAE), etc.) est-elle en place?', 0, '', ' Selon le Livre blanc de l\'action GreenConcept : Chaque octet a un impact. Il faut donc réduire au maximum la quantité de données produites, traitées, transportées et stockées.\r\nLa donnée est en effet au cœur du sujet de la sobriété numérique puisque c\'est afin de la traiter, de la stocker, ou encore de la transférer que les infrastructures numériques sont mises en place. ', NULL, 2, 0),
('eae87dc3-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', NULL, NULL, 'Quelles sont les modalités de stockage et de sauvegarde de vos données informatiques (solutions logicielles, sites et applications hébergés, sauvegarde externalisée...)?', 0, '', ' La sauvegarde des données numériques est indispensable pour toute structure et ne doit pas être négligée. C\'est la clé de la reprise/continuité d\'activité suite à tout incident informatique (bug, cyberattaque...). \r\nSi la sobriété numérique invite à rationnaliser le système d\'information (SI), cela ne doit pas être au détriment de la disponibilité des données essentielles. L\'équilibre tient à l\'adoption d\'une politique de sauvegarde adaptée aux besoins de votre structure. ', NULL, 3, 1),
('eae8bb58-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', 'eae87dc3-06bc-11ee-b776-0cc47a39c2c0', '0d1ca6c8-06bd-11ee-b776-0cc47a39c2c0', 'Une politique de gestion des supports de sauvegarde (répartition des données, choix du type de support selon la nature et la disponibilité attendue, etc.) est-elle définie? ', 0, '', ' Plus un dispositif de stockage de données est performant, plus il consomme d\'énergie. L\'écart entre la technologie la plus sobre et la plus énergivore peut varier d\'un facteur 30. C\'est pourquoi il est préférable d\'adapter le support à la disponibilité des données attendue. ', NULL, 4, 1),
('eae8f743-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', 'eae87dc3-06bc-11ee-b776-0cc47a39c2c0', '0d1ca6c8-06bd-11ee-b776-0cc47a39c2c0', 'Favorisez-vous les centres de données qui prennent des engagements environnementaux? ', 0, 'Le PUE est un indicateur mis au point pour mesurer l\'efficacité énergétique d\'un data center. Il est calculé en divisant le total de l\'énergie consommée par le datacenter par le total de l\'énergie utilisée par les équipements informatiques (serveur, stockage, réseau). Ainsi, plus le résultat du PUE est proche de 1, moins le data center consomme d\'énergie. \r\nD\'autres indicateurs complémentaires existent comme le WUE (Water Usage Effectiveness) ou encore le CUE (Carbon Usage Effectiveness). ', ' Contrairement à ce que pensent généralement les personnes interrogées, les centres de données (ou datas centers) ont un impact plus faible, par comparaison avec les terminaux des utilisateurs. Toutefois, il reste important de privilégier ceux qui s\'engagent pour plus de sobriété numérique compte tenu du volume toujours plus important de données qui y sont stockées et de services numériques qui en dépendent.', NULL, 5, 1),
('eae938d8-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', 'eae87dc3-06bc-11ee-b776-0cc47a39c2c0', '0d1ca6c8-06bd-11ee-b776-0cc47a39c2c0', 'Votre structure dispose-t-elle d\'une ou plusieurs salles serveurs/centres de données internes ? Si oui, quelles en sont les modalités d\'agencement et de gestion (organisation des baies, température moyenne de fonctionnement…) ?', 0, '', ' Les modalités d\'agencement et de gestion des salles serveurs/centres de données influent grandement sur leur efficacité énergétique et, plus largement, leur impact environnemental. ', NULL, 7, 1),
('eae9732c-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', 'eae938d8-06bc-11ee-b776-0cc47a39c2c0', 'a85ac5ce-09e2-11ee-9ecf-0cc47a39c2c2', 'Quelle est la durée de vie moyenne de vos serveurs?', 0, '', '  D\'après le Baromètre des pratiques Green IT des entreprises en France 2020 : 79 % des entreprises qui ont adopté une stratégie Green IT déclarent que leurs serveurs ont une durée de vie moyenne de plus de 5 ans. En face, 76 % des entreprises n\'ayant pas adopté de stratégie Green IT déclarent une durée de vie moyenne de leurs serveurs inférieure à 3 ans. ', NULL, 8, 1),
('eae9ad81-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', 'eae87dc3-06bc-11ee-b776-0cc47a39c2c0', '0d1ca6c8-06bd-11ee-b776-0cc47a39c2c0', 'Connaissez-vous la proportion de serveurs physiques et virtuels (aussi appelés Virtual machine (VM)) voire le taux de virtualisation de votre structure?', 0, '', ' Le taux de virtualisation correspond à la formule suivante : nombre de serveurs virtuels/nombre de serveurs physiques. ', NULL, 9, 1),
('eae9e800-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', NULL, NULL, 'Quelle est la capacité de stockage/utilisateur de votre structure (tous supports confondus)? ', 0, '', ' Une capacité de stockage surdimensionnée, c\'est le risque que des ressources soient mobilisées de façon non pertinente avec tous les coûts et impacts que cela implique. ', NULL, 10, 1),
('eaea20ae-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', NULL, NULL, 'Selon quelle modalité est-il possible de partager des documents en interne et à l\'externe ?', 0, '', ' Selon l\'Institut du Numérique Responsable (INR) : Mettre en place des dossiers de partage de documents (ou espace de travail de travail collaboratif) permet d\'éviter l\'envoi de pièces jointes volumineuses et la duplication des documents sur différents postes de travail ou dans différents dossiers.', NULL, 11, 1),
('eaea5d42-06bc-11ee-b776-0cc47a39c2c0', '0', 'd573027d-432d-11ed-af88-040300000000', NULL, NULL, 'Assurez-vous un suivi de la volumétrie des données numériques traitées via votre système d\'information (SI)? ', 0, '', ' Le suivi de la volumétrie des données numériques est un préalable à l\'adaptation et l\'optimisation de la politique de stockage et de gestion des données de votre structure. ', NULL, 12, 1),
('eaea942d-06bc-11ee-b776-0cc47a39c2c0', '0', '54aa9a19-432e-11ed-af88-040300000000', NULL, NULL, 'Des obligations et/ou bonnes pratiques favorisant la sobriété numérique (gestion et tri des boîtes de messagerie, espaces de stockage en ligne, mise en veille et extinction des outils numériques...) ont-elles été mises en place via la charte informatique ou tout autre support ou format? ', 0, '', ' La charte informatique est le document indiqué pour assurer la diffusion et l\'opposabilité des règles et pratiques communes définies par la structure concernant le numérique (sécurité informatique, protection des données, usages autorisés, sanctions, etc.). ', NULL, 1, 0),
('eaead655-06bc-11ee-b776-0cc47a39c2c0', '0', '54aa9a19-432e-11ed-af88-040300000000', NULL, NULL, 'Votre structure fait-elle un usage régulier de la visioconférence? ', 0, '', ' Tout comme les déplacements, la visioconférence a des impacts environnementaux qu\'il faut prendre en compte pour définir le format le plus approprié pour la tenue d\'une réunion (terminaux utilisés pour y participer, réseaux utilisés, nombre de participants, durée de la réunion...). \r\nÀ noter que d\'après une étude menée par des chercheurs de l\'université Purdue, de l\'université de Yale et du Massachusetts Institute of Technology, désactiver la webcam réduit de 96% l\'impact environnemental lié à la visioconférence.', NULL, 2, 0),
('eaeb0f2f-06bc-11ee-b776-0cc47a39c2c0', '0', '54aa9a19-432e-11ed-af88-040300000000', NULL, NULL, 'Le télétravail est-il en place? ', 0, '', ' Bien que la mise en place du télétravail implique de nouveaux impacts qu\'il est nécessaire de prendre en compte dans son déploiement afin d\'éviter le phénomène des effets de rebond, sa mise en place permet, dans de nombreux contextes, de réduire les émissions de gaz à effets de serre liées aux déplacements. Selon une récente étude de l\'ADEME (2020) : En conclusion, l\'ensemble des effets rebond identifiés (déplacements supplémentaires, relocalisation du domicile, usage de la visioconférence, consommations énergétiques du domicile...) peuvent réduire en moyenne de 31 % les bénéfices environnementaux du télétravail. Cependant, si l\'on prend en compte également les effets positifs induits - en particulier ceux générés par le flex office organisé, nous obtenons une balance positive de + 52 %. Ces bénéfices sont significatifs et justifient l\'encouragement du développement du télétravail, dans un contexte où il est par ailleurs plébiscité par les salariés eux-mêmes en raison de ses avantages individuels (qualité de vie, gain de temps et d\'argent, etc.).', NULL, 3, 0),
('eaeb4f85-06bc-11ee-b776-0cc47a39c2c0', '0', '54aa9a19-432e-11ed-af88-040300000000', NULL, NULL, 'Avez-vous mis en place des consignes particulières favorisant la sobriété numérique en matière d\'impression de documents (police imposée, nombre limité d\'impressions...)? ', 0, '', ' En moyenne, un français imprime 20 pages par jour, ce qui représente, notamment, par personne et par an : \n- 6 600 pages imprimées ; \n- 1 arbre utilisé ; \n- 12 500 litres d\'eau consommés. \nOr, derrière ces chiffres, il faut tenir compte du fait que : \n- les e-mails représentent 10 à 38% du volume d\'impression ; \n- 16% des impressions ne sont jamais lues et 65% pourraient être lues sur un écran ; \n- ¼ des impressions sont jetées dans les 5 minutes suivant l\'impression.\nIl est donc nécessaire d\'agir pour réduire l\'impact des impressions. ', NULL, 4, 0),
('eaeb8dc2-06bc-11ee-b776-0cc47a39c2c0', '0', '54aa9a19-432e-11ed-af88-040300000000', NULL, NULL, 'La collecte et le recyclage du papier sont-ils réalisés au sein de votre structure? ', 0, '', ' Décret Tri 5 flux : \r\nDans le prolongement de la loi sur la transition énergétique, et en complément de l\'obligation sur le tri et la valorisation des emballages professionnels (Art. R 543-66 à 72 du code de l\'Environnement), le décret n°2016-288 du 10 mars 2016 oblige depuis le 1er juillet 2016 au tri à la source et à la valorisation de 5 flux de déchets (Art. D 543 à 287 du code de l\'Environnement), à savoir : papier/carton, métal, plastique, verre et bois.', NULL, 5, 0);
INSERT INTO `question` (`id`, `theme_id`, `category_id`, `parent_id`, `parent_answer_id`, `question`, `multiple`, `definition`, `additional_information`, `definition_title`, `sort_order`, `level_two`) VALUES
('eaebdb76-06bc-11ee-b776-0cc47a39c2c0', '0', '708d624a-432f-11ed-af88-040300000000', NULL, NULL, 'Les services numériques (logiciels, applications...) utilisés sont-ils écoconçus? ', 0, '', ' Selon la Mission interministérielle Numérique Écoresponsable (MiNumÉco) : L\'écoconception des services numériques n\'est pas uniquement une recherche d\'optimisation, d\'efficience ou de performance mais une réflexion plus globale sur l\'usage des technologies. Il est important d\'intégrer les impacts environnementaux du numérique dans la conception des services numériques en visant directement ou indirectement à allonger la durée des vies des équipements numériques, à réduire la consommation de ressources informatiques et énergétiques des terminaux, des réseaux et des centres de données.\r\nPar exemple, lorsqu\'un service de communication en ligne présente des erreurs dans son code ou que celui-ci est rédigé de façon complexe, les navigateurs internet prennent plus de temps pour en charger le contenu car ils doivent au préalable compenser ces erreurs et déchiffrer l\'ensemble, ce qui implique un impact environnemental plus important. ', NULL, 1, 0),
('eaec1930-06bc-11ee-b776-0cc47a39c2c0', '0', '708d624a-432f-11ed-af88-040300000000', NULL, NULL, 'Vos services de communication au public en ligne (principalement sites internet et applications mobiles) sont-ils écoconçus?', 0, 'Services de communication au public en ligne : Selon le Référentiel Général d\'Amélioration de l\'Accessibilité (RGAA), \'\'Les services de communication au public en ligne sont définis comme toute mise à disposition du public ou de catégories de public, par un procédé de communication électronique, de signes, de signaux, d\'écrits, d\'images, de sons ou de messages de toute nature qui n\'ont pas le caractère d\'une correspondance privée (article 1er de la loi n° 2004-575 du 21 juin 2004 pour la confiance dans l\'économie numérique). Conformément au II de l\'article 47 de la loi du 11 février 2005, ils comprennent notamment :\r\nles sites internet, intranet, extranet ; les progiciels, dès lors qu\'ils constituent des applications utilisées au travers d\'un navigateur web ou d\'une application mobile ;\r\nles applications mobiles qui sont définies comme tout logiciel d\'application conçu et développé en vue d\'être utilisé sur des appareils mobiles, tels que des téléphones intelligents (smartphones) et des tablettes, hors système d\'exploitation ou matériel ;\r\nle mobilier urbain numérique, pour leur partie applicative ou interactive, hors système d\'exploitation ou matériel.\'\'', '', NULL, 2, 0),
('eaec7d75-06bc-11ee-b776-0cc47a39c2c0', '0', '708d624a-432f-11ed-af88-040300000000', 'eaec1930-06bc-11ee-b776-0cc47a39c2c0', '0d22ccc7-06bd-11ee-b776-0cc47a39c2c0', 'Un suivi statistiques et/ou le dépôt de cookies et autres traceurs sont-ils appliqués aux services de communication au public en ligne (principalement sites internet et applications mobiles) de votre structure? ', 0, '', ' Les cookies et autres traceurs ainsi que les personnalisations qu\'ils rendent possibles ont un impact environnemental important, aussi est-il préférable de réduire leur utilisation au strict minimum afin d\'alléger le poids environnemental d\'un service de communication en ligne (site internet, application mobile...). \r\nCela rejoint par ailleurs le principe de pertinence et de minimisation des données collectées posé par le RGPD. ', NULL, 2, 1),
('eaecba23-06bc-11ee-b776-0cc47a39c2c0', '0', '708d624a-432f-11ed-af88-040300000000', NULL, NULL, 'Les personnes en charge de la communication sont-elles au fait des principes de la sobriété éditoriale? ', 0, '', ' D\'après le Shift Project, le trafic de données est responsable de plus de la moitié de l\'impact énergétique mondial du numérique, avec 55 % de sa consommation d\'énergie annuelle. Chaque octet transféré ou stocké sollicite des terminaux et des infrastructures de grande envergure, gourmandes en énergie (centres de données, réseaux). \nEn 2018, les flux vidéo représentaient 80 % des flux de données mondiaux et 80 % de l\'augmentation de leur volume annuel. Les 20 % restants étaient constitués de sites web, de données, de jeux vidéo, etc. La croissance rapide du volume total de données - donc de la consommation d\'énergie et des émissions de gaz à effet de serre associées – est ainsi en très large partie due à la vidéo.\nLa sobriété éditoriale vise à réduire ces différents impacts par la mise en place d\'une communication raisonnée et adaptée aux besoins de votre structure et des personnes auxquelles elle s\'adresse. ', NULL, 3, 0),
('eaecfa36-06bc-11ee-b776-0cc47a39c2c0', '0', '708d624a-432f-11ed-af88-040300000000', NULL, NULL, 'Avez-vous imposé des règles particulières en matière de traitement de texte et autres documents bureautiques (police d\'écriture, tailles et couleurs des caractères, marges, format de documents (Word, PDF, etc.), etc.)? ', 0, '', ' Le choix de la police d\'écriture ou encore la taille des caractères, mais aussi les couleurs et bien d\'autres paramètres sont susceptibles de réduire l\'impact environnemental du traitement de texte et autre fichiers des suites bureautiques, particulièrement sur la phase d\'impression. ', NULL, 4, 1),
('eaed3454-06bc-11ee-b776-0cc47a39c2c0', '0', '708d624a-432f-11ed-af88-040300000000', 'eaecfa36-06bc-11ee-b776-0cc47a39c2c0', '0d23f9f5-06bd-11ee-b776-0cc47a39c2c0', 'Votre structure dispose-t-elle d\'une charte graphique? ', 0, '', ' Une charte graphique assure l\'uniformisation des documents produits par la structure tout en permettant de rationnaliser la consommation d\'encre et de papier, réduisant ainsi l\'impact environnemental des impressions et supports de communication. C\'est par ailleurs l\'occasion d\'intégrer des principes d\'accessibilité afin de s\'assurer que les documents puissent être consultés et compris par tous. ', NULL, 5, 1),
('eaed725d-06bc-11ee-b776-0cc47a39c2c0', 'ffef7f08-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Le montant total annuel des achats de votre structure est-il supérieur à 50 millions d\'euros HT? ', 0, '', '', NULL, 1, 1),
('eaedab44-06bc-11ee-b776-0cc47a39c2c0', 'ffef7f08-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', 'eaed725d-06bc-11ee-b776-0cc47a39c2c0', '0d24ba23-06bd-11ee-b776-0cc47a39c2c0', 'Votre structure a-t-elle adopté un schéma de promotion des achats publics socialement et écologiquement responsables?', 0, '', '', NULL, 2, 1),
('eaede4b2-06bc-11ee-b776-0cc47a39c2c0', 'ffef7f08-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Des clauses sociales sont-elles inclues dans les appels d\'offre et contrats conclus hors marché? ', 0, '', ' Il est nécessaire de tenir compte des conditions de travail et de vie des personnes qui fabriquent les équipements et services numériques.\r\nCela peut également être un outil pour promouvoir le retour à l\'emploi de personnes qui en sont éloignées. \r\nCela s\'inscrit enfin dans les objectifs du Plan National des Achats Responsables (PNAD) 2022-2025 et notamment celui visant à ce que, d\'ici 2025, 30% des contrats de la commande publique notifiés au cours de l\'année comprennent au moins une considération sociale. ', NULL, 3, 1),
('eaee2338-06bc-11ee-b776-0cc47a39c2c0', 'ffef7f08-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Tenez-vous compte du Débit d\'Absorption Spécifique (DAS) dans le cadre des achats numériques? ', 0, 'Le DAS évalue l\'énergie de sondes électromagnétiques qu\'absorbe le corps humain lors de l\'utilisation d\'un équipement radioélectrique tel qu\'un téléphone. Il s\'exprime en watt par kilogramme (W/kg) et se divise en trois types correspondant chacun à une partie du corps et aux usages propres à chacune d\'elles : le DAS tête, le DAS tronc et le DAS membre. \r\nLe DAS de chaque téléphone mis sur le marché doit être contrôlé en laboratoire pour respecter la réglementation européenne. ', ' Selon L\'Institut du Numérique Responsable (INR) : En 2011, l\'Organisation Mondiale de la Santé (OMS) a classé les champs de radiofréquences électromagnétiques émis par les terminaux mobiles connectés (téléphones, smartphones, tablettes, etc.) comme « potentiellement cancérigènes ». En 2015, la France a voté la « loi relative à la sobriété, à la transparence, à l\'information et à la concertation en matière d\'exposition aux ondes électromagnétiques ». Cette loi impose l\'application des principes de précaution et de sobriété face aux émissions d\'ondes électromagnétiques (antennes relais, téléphones portables et smartphones, box internet, etc.).', NULL, 4, 1),
('eaee6416-06bc-11ee-b776-0cc47a39c2c0', 'ffef7f08-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Faites-vous appel à des acteurs locaux de la réparation, du réemploi et/ou de la réutilisation d\'équipements informatiques?', 0, '\"Le concept d\'économie sociale et solidaire (ESS) désigne un ensemble d\'entreprises organisées sous forme de coopératives, mutuelles, associations, ou fondations, dont le fonctionnement interne et les activités sont fondés sur un principe de solidarité et d\'utilité sociale.  Ces entreprises adoptent des modes de gestion démocratiques et participatifs. Elles encadrent strictement l\'utilisation des bénéfices qu\'elles réalisent : le profit individuel est proscrit et les résultats sont réinvestis. Leurs ressources financières sont généralement en partie publiques.  Elles bénéficient d\'un cadre juridique renforcé par la loi n° 2014-856 du 31 juillet 2014 modifiée relative à l\'économie sociale et solidaire.\" Pour plus d’informations voir : https://www.economie.gouv.fr/cedef/economie-sociale-et-solidaire ', '', NULL, 5, 1),
('eaee9d7f-06bc-11ee-b776-0cc47a39c2c0', 'ffef8496-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Votre structure mène-t-elle une démarche de mise en conformité aux règles relatives à la protection des données (Règlement Général sur la Protection des Données (RGPD), Loi Informatique et Libertés (LIL)...)? ', 0, '', ' Depuis le 25 mai 2018, l\'article 37 du RGPD, oblige les organismes publics à désigner un délégué à la protection des données (DPD) chargé de veiller à la gestion et à la protection de ces dernières, en toute indépendance et conformément aux obligations énumérées par ce règlement.\r\nOrganismes publics comme privés doivent se conformer aux règles applicables en matière de protection des données, principalement le Règlement Général sur la Protection des Données (RGPD). ', NULL, 1, 1),
('eaeed982-06bc-11ee-b776-0cc47a39c2c0', 'ffef8496-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Des actions de sensibilisation sont-elles menées auprès du personnel sur les enjeux et bonnes pratiques en matière de protection des données et de sécurité informatique? ', 0, '', '', NULL, 2, 1),
('eaef0f77-06bc-11ee-b776-0cc47a39c2c0', 'ffef8496-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Des actions de sensibilisation sont-elles menées auprès des élus sur les enjeux et bonnes pratiques en matière de protection des données et de sécurité informatique? ', 0, '', '', NULL, 3, 1),
('eaef4a05-06bc-11ee-b776-0cc47a39c2c0', 'ffef8496-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Une politique de protection contre les risques cyber a-t-elle été adoptée pour votre structure? ', 0, '', ' La sécurité informatique contribue à l\'allongement de la durée de vie des outils numériques. En effet, en cas d\'attaque cyber, il est parfois nécessaire de renouveler une partie voire l\'intégralité du parc numérique. \r\nPar ailleurs, elle participe également aux mesures de sécurité qui s\'imposent au responsable de traitement dans le cadre du RGPD afin de prévenir les violations de données personnelles. ', NULL, 4, 1),
('eaef89eb-06bc-11ee-b776-0cc47a39c2c0', 'ffef8496-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Avez-vous réalisé l\'homologation au Référentiel Général de Sécurité (RGS) de votre système d\'information (SI)? ', 0, '', ' L\'homologation RGS vise à la sécurisation du système d\'information qui figure parmi les objectifs de la stratégie numérique responsable telle que définie par la loi REEN et son décret d\'application. \r\nÀ noter que ce processus est obligatoire pour les organismes publics disposant de téléservices. ', NULL, 5, 1),
('eaefc832-06bc-11ee-b776-0cc47a39c2c0', 'ffef87b9-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Votre structure a-t-elle mis en place une démarche en faveur de l\'inclusion numérique? ', 0, 'L\'inclusion numérique s\'entend tant par l\'accès matériel aux outils numériques et réseaux de communication (notamment pour les personnes éloignées du numérique par manque de moyens ou d\'infrastructures) que par l\'accès effectif de tous aux services de communication au public en ligne (notamment pour les personnes ayant des difficultés avec le numérique ou dont l\'accès est conditionné par l\'accessibilité dudit service). ', ' Face à la dématérialisation des services publics, il est indispensable d\'œuvrer en faveur de l\'inclusion numérique afin de ne pas générer d\'inégalités et situations discriminatoires dans le cadre de vos services de communication au public en ligne et ceux de vos partenaires institutionnels. ', NULL, 1, 1),
('eaf00a4e-06bc-11ee-b776-0cc47a39c2c0', 'ffef87b9-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Des actions de sensibilisation sont-elles menées auprès du personnel sur les enjeux et bonnes pratiques en matière d\'inclusion numérique? ', 0, '', '', NULL, 2, 1),
('eaf0418a-06bc-11ee-b776-0cc47a39c2c0', 'ffef87b9-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Des actions de sensibilisation sont-elles menées auprès des élus sur les enjeux et bonnes pratiques en matière de protection d\'inclusion numérique? ', 0, '', '', NULL, 3, 1),
('eaf0788d-06bc-11ee-b776-0cc47a39c2c0', 'ffef87b9-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Votre structure respecte-t-elle les préconisations et obligations en matière d\'accessibilité numérique? ', 0, 'Rendre possible l\'accès à l\'information et aux fonctionnalités d\'un service de communication au public en ligne, quelle que soit la nature du handicap des personnes et la façon dont elles consultent l\'information. Concrètement, c\'est un ensemble de règles et de bonnes pratiques graphiques, fonctionnelles et techniques, permettant de s\'assurer que les services de communication sont accessibles aux personnes handicapées.', ' Les organismes publics et quelques catégories d\'acteurs privés (notamment ceux bénéficiant d\'une délégation de service public, recevant des fonds publics ou encore en partie contrôlés par un organisme public) ont des obligations à respecter en vertu de la loi n°2005-102 et du décret n°2019-768 afin que leurs services de communication au public en ligne soient accessibles aux personnes handicapées. Cela implique de respecter un ensemble de règles posées par le Référentiel Général d\'Amélioration de l\'Accessibilité (RGAA). ', NULL, 4, 1),
('eaf0bf23-06bc-11ee-b776-0cc47a39c2c0', 'ffef8a66-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Votre structure respecte-t-elle les préconisations et obligations en matière d\'ouverture de ses données (Open Data )? ', 0, 'L\'open data désigne un mouvement, né en Grande-Bretagne et aux États-Unis, d\'ouverture et de mise à disposition des données produites et collectées par les services publics (administrations, collectivités locales...).', ' Dans une société où l\'information est devenue une richesse, l\'Open data, ou l\'ouverture des données publiques, permet de mettre en commun des données qui deviendront, à leur tour, de l\'information. \r\nLa loi NOTRe est un texte fondateur pour l\'ouverture des données publiques. Depuis 2016, la loi pour une République Numérique et le décret n°2016-360 relatif aux marchés publics ont renforcé le cadre juridique de l\'Open data en rendant obligatoires plusieurs dispositions pour les collectivités territoriales.\r\nLes collectivités de plus de 3 500 habitants et comptant au moins 50 agents doivent publier certaines catégories de documents administratifs, notamment « toutes les informations dont la publication présente un intérêt économique, social, sanitaire ou environnemental ».', NULL, 1, 1),
('eaf0fe3d-06bc-11ee-b776-0cc47a39c2c0', 'ffef8d65-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Mettez -vous à disposition du public des bornes d\'accès/une connexion Wifi gratuite? ', 0, '', ' D\'après l\'ADEME : Pour utiliser son téléphone mobile, une connexion Wifi consomme moins et sollicite moins le réseau que la 4G (ou la 5G).\r\nEn complément, selon le Livre blanc de l\'action GreenConcept : Les impacts environnementaux de la transmission d\'un GigaOctet via le réseau 4G sont jusqu\'à 20 fois plus important que via le réseau ADSL et Wifi. ', NULL, 1, 1),
('eaf1cc7a-06bc-11ee-b776-0cc47a39c2c0', 'ffef8d65-0699-11ee-b776-0cc47a39c2c0', '526bb3e9-0156-11ee-b776-0cc47a39c2c0', NULL, NULL, 'Souhaitez-vous diffuser les enjeux et bonnes pratiques du numérique responsable auprès du public? ', 0, 'Le numérique responsable est une démarche d\'amélioration continue qui vise à améliorer l\'empreinte écologique et sociale du numérique. ', ' La place centrale des collectivités territoriales dans le quotidien des administrés et acteurs locaux en font un levier clé pour la bonne diffusion des enjeux et bonnes pratiques du numérique responsable. ', NULL, 2, 1),
('fd893fe8-4af6-11ee-b615-0cc47a39c2c2', 'b11043a2-0453-11ee-b776-0cc47a39c2c0', '8444bdb4-432a-11ed-af88-040300000000', 'eae0b739-06bc-11ee-b776-0cc47a39c2c0', '0d0d8749-06bd-11ee-b776-0cc47a39c2c0', 'Combien d\'imprimantes/copieurs sont-ils mis à disposition des utilisateurs et quelles sont les modalités de répartitions ?', 0, '', 'L\'optimisation du parc d\'impression est primordiale. Elle permet d\'ajuster l\'utilisation de l\'outil au juste besoin et ainsi de réduire les impacts liés à la fabrication du matériel, les consommations d\'énergie, et plus largement les coûts liés au parc. \r\nA noter qu\'une grande partie des consommations d\'énergie ne résultent pas des impressions mais des temps de veille/d\'arrêt des imprimantes, notamment de nuit et durant les week-ends. En effet, qu\'ils soient en veille ou éteints, les outils numériques laissés branchés consomment toujours de l\'énergie. ', '', 10, 1);
INSERT INTO `recommandation` (`id`, `question_id`, `level_id`, `status_id`, `title`, `body`, `short_title`, `details`) VALUES
('01ab58b1-4af5-11ee-b615-0cc47a39c2c2', '6c5a609b-4af4-11ee-b615-0cc47a39c2c2', 2, 4, 'À votre connaissance, votre structure a-t-elle pris en compte la sobriété numérique et la transition environnementale dans ses actions et projets en lien avec le numérique ?', 'Mettre en place une gouvernance de la démarche vers un numérique plus sobre (désignation d\'un référent opérationnel/élu, création d\'un comité de pilotage, rédaction d\'un plan d\'actions...).', 'Mettre en place une gouvernance', ''),
('036c12fc-4b00-11ee-b615-0cc47a39c2c2', 'a950ed4d-4aff-11ee-b615-0cc47a39c2c2', 0, 4, 'Les élus de votre structure ont-ils été formés aux enjeux et bonnes pratiques en matière de sobriété numérique ?', 'Former les élus les plus concernés aux enjeux et bonnes pratiques de la sobriété numérique.', 'Formation des élus', NULL),
('0688903e-4678-11ee-b615-0cc47a39c2c2', 'ead8f657-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Ces personnes sont-elles à temps plein sur ces missions ?', 'Les besoins en ETP (équivalent temps plein) peuvent fortement varier en fonction de l\'ampleur du SI d\'une collectivité et de la manière dont elle met à disposition et maintient l\'accès à divers services numériques pour ses agents et administrés. Il est donc avant tout question de proportionnalité, en évitant l\'écueil du manque de moyens comme son opposé de la sur-allocation.', 'Missions \"Sobriété numérique\" des agents et autres personnels', ''),
('100251a8-09ba-11ee-b881-0cc47a39c2c2', 'eadfd1c0-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'L\'architecture de votre système d\'information est-elle optimisée par rapport aux besoins de votre structure ? ', 'Effectuer une revue des solutions logicielles et applications déployées afin d\'en étudier l\'utilité et l\'utilisation réelles. Désinstaller celles qui ne sont pas utilisées ou n\'apportent pas de plus-value à votre structure et privilégier une architecture applicative modulaire.', 'Décommissionnement des services numériques', ''),
('100256a2-09ba-11ee-b881-0cc47a39c2c2', 'eae0041e-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Quelle est la durée de vie moyenne des postes informatiques de votre structure ? ', 'Documenter la durée de vie moyenne des postes informatiques afin d\'en suivre l\'évolution.', 'Durée de vie moyenne des équipements numériques', ''),
('100259dd-09ba-11ee-b881-0cc47a39c2c2', 'eae03ede-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Quelle est la durée de vie moyenne des copieurs/imprimantes de votre structure ? ', 'Documenter la durée de vie moyenne copieurs/imprimantes afin d\'en suivre l\'évolution.', 'Durée de vie moyenne des copieurs et imprimantes', ''),
('10025cc4-09ba-11ee-b881-0cc47a39c2c2', 'eae07ac9-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Quelle est la durée de vie moyenne des téléphones de votre structure ?', 'Documenter la durée de vie moyenne téléphones afin d\'en suivre l\'évolution.', 'Durée de vie moyenne des téléphones', ''),
('10025f8d-09ba-11ee-b881-0cc47a39c2c2', 'eae246b3-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'L\'utilisation des outils professionnels à des fins personnelles et/ou l\'utilisation d\'outils personnels à des fins professionnelles est-elle autorisée ?', 'Autoriser l\'utilisation des outils numériques professionnels sur le temps personnel et/ou favoriser la pratique du BYOD (Bring Your Own Device). À noter toutefois que cette dernière est fortement déconseillée par l\'ANSSI (Agence nationale de la sécurité des systèmes d\'information) pour des raisons de sécurité du système d\'information. Sa mise en place est envisageable sous réserve de bien l\'encadrer. \nCes pratiques doivent dans tous les cas être encadrées par un document de type charte informatique afin de ne pas remettre en cause la sécurité du système d\'information, la protection des données personnelles, ainsi que le nécessaire cloisonnement entre vie privée et vie professionnelle. Consulter les ressources humaines, le DPO et/ou le RSSI de votre structure pour un accompagnement.', 'Mutualisation des usages professionnels et personnels', ''),
('1002624a-09ba-11ee-b881-0cc47a39c2c2', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Avez-vous mis en place des consignes et pratiques de nature à allonger la durée de vie de vos équipements numériques (favoriser la réparation avant le remplacement, dissocier le remplacement des équipements selon les besoins, maintenance...) ?', 'Mettre en place des consignes et pratiques de nature à allonger la durée de vie de vos équipements numériques (favoriser la réparation avant le remplacement, dissocier le remplacement des équipements selon les besoins, assurer une maintenance régulière...).', 'Consignes et pratiques pour allonger de la durée de vie des équipements numériques', ''),
('10026519-09ba-11ee-b881-0cc47a39c2c2', 'eae4a1db-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'La maintenance informatique (matériel et logiciels) est-elle assurée de façon régulière ? ', 'Etudier la pertinence de mettre à jour une solution logicielle ou un système d\'exploitation avant d\'y procéder. Seules les mises à jour de sécurité sont indispensables, les autres n\'apportant que des évolutions de fonctionnalités diverses. \r\nCette étude doit être réalisée avec le concours du service compétent ou le prestataire pour prévenir tout risque d\'atteinte à la sécurité du système d\'information (SI).', 'Pertinence des mises à jour proposées', ''),
('100268ee-09ba-11ee-b881-0cc47a39c2c2', 'eae552de-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Avez-vous mis en place des consignes et pratiques de nature à réduire la consommation d\'énergie de votre parc informatique (mise en veille, extinction des équipements, paramétrage de la luminosité, suivi des consommations...) ? ', 'Appliquer et diffuser les bonnes pratiques favorisant les économies d\'énergie dans l\'utilisation des équipements numériques. Cela contribuera également à allonger la durée de vie de leur batterie et donc des équipements eux-mêmes.', 'Économie d\'énergie du parc numérique', 'Appliquer et diffuser les bonnes pratiques favorisant les économies d\'énergie dans l\'utilisation des équipements numériques afin d\'allonger la durée de vie de leur batterie et donc la durée de vie des équipements eux-mêmes :  - Privilégier le mode d\'alimentation le plus économique/écologique (paramétrage de la batterie, mode économie d\'énergie par exemple).  - Mettre en veille les équipements numériques dès qu\'ils ne sont pas utilisés ou les éteindre en cas d\'inactivité prolongée (30 minutes à une heure d\'inactivité environ).  - Adapter la luminosité de l\'écran selon les besoins.  - Limiter le nombre de programmes ouverts et inutilisés. Les fermer en cas d\'absence (pause du midi notamment) afin d\'éviter l\'envoi de requêtes inutiles.  - Désactiver les fonctions GPS, Wifi, Bluetooth et autres lorsqu\'elles ne sont pas utilisées.  - Éteindre les écrans et autres équipements non utilisés.'),
('10026bd4-09ba-11ee-b881-0cc47a39c2c2', 'eae8bb58-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Une politique de gestion des supports de sauvegarde (répartition des données, choix du type de support selon la nature et la disponibilité attendue, etc.) est-elle définie ? ', 'Sous réserve que cela ne porte pas atteinte à la disponibilité des données et à la continuité d\'activité, désactiver les transferts automatiques de données et assurer un tri régulier des espaces de stockage hébergés (cloud), dans le respect des durées de conservation et règles d\'archivage qui s\'imposent à la structure. \r\nSe rapprocher du service compétent ou du prestataire pour un accompagnement.                                                                                                               ', '', ''),
('10026eb6-09ba-11ee-b881-0cc47a39c2c2', 'eae8f743-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Favorisez-vous les centres de données qui prennent des engagements environnementaux ? ', 'Privilégier les centres de données installés sur le territoire français : au-delà des enjeux de protection et de souveraineté des données numériques, le mix énergétique français est plus favorable à la maîtrise de l\'empreinte environnementale de ces infrastructures.', 'Centres de données français', ''),
('10027220-09ba-11ee-b881-0cc47a39c2c2', 'eae9732c-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Quelle est la durée de vie moyenne de vos serveurs ?', 'Documenter la durée de vie moyenne des serveurs physiques afin d\'en suivre l\'évolution.', '', ''),
('100274d4-09ba-11ee-b881-0cc47a39c2c2', 'eaea942d-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Des obligations et/ou bonnes pratiques favorisant la sobriété numérique (gestion et tri des boîtes de messagerie, espaces de stockage en ligne, mise en veille et extinction des outils numériques...) ont-elles été mises en place via la charte informatique ou tout autre support ou format ? ', 'Appliquer et diffuser les principes de la sobriété numérique à la gestion des boîtes mail (rédaction, pièces jointes, , tri, paramétrages, etc.), à la navigation en ligne (choix du navigateur, recherches, etc.) ou encore à l\'écoute de musique et autres contenus audiovisuels durant le temps de travail (streaming, choix du média, etc...).', 'Diffusion des bonnes pratiques en interne', 'Appliquer et diffuser les principes de la sobriété numérique à la gestion des boîtes mail :  - Assurer un tri régulier de sa boîte mail, dans le respect des durées de conservation et règles d\'archivage qui s\'imposent à la structure ;  - Se désabonner des newsletters inutiles ;  - Installer un anti-spams ; - Réduire autant que possible le nombre d\'emails envoyés : il préférable, lorsqu\'il peut être évité, de privilégier un canal de transmission d\'informations moins impactant (SMS, appel...) ;  - Privilégier le format texte au format HTML pour la rédaction d\'emails. Ce dernier format ne doit être utilisé que lorsque cela est indispensable ;  - Réduire le contenu de l\'email à l\'essentiel afin de réduire les temps d\'écriture et de lecture ;  - A l\'externe : Partager un lien vers le lieu de stockage en ligne institutionnel ou temporaire (cloud interne ou plateforme de partage en ligne) d\'un document plutôt que d\'en joindre une copie au mail envoyé. A défaut, compresser la taille des pièces jointes ; A l\'interne : privilégier le partage via serveur ou messagerie instantanée ;   - Bien cibler ses destinataires et n\'utiliser la fonctionnalité \"Répondre à tous\" que lorsque cela est réellement nécessaire ;  - Créer une signature sans image ni logo au moins pour les échanges internes ;  - Supprimer les pièces jointes des emails transférés ou auxquels une réponse est envoyée.  Appliquer et diffuser les principes de la sobriété numérique à la navigation en ligne :  - Fermer les pages et onglets inutilisés ;  - Vider le cache, supprimer les cookies et historique de navigation des navigateurs ; - Ajouter une solution bloquant la recharge des onglets ;  - Mettre en favoris/marque-pages les sites régulièrement consultés ;  - Choisir un navigateur internet moins énergivore (Chrome serait l\'un des plus gourmands devant Internet Explorer et Firefox) ;  - Se rendre directement sur le site en tapant l\'adresse dans la barre d\'url ou via les favoris et l\'historique plutôt que de lancer une recherche via un moteur de recherches ;  - Utiliser les mots clés les plus précis possible pour les recherches en ligne.   Ecoute de musique et autres contenus audiovisuels durant le temps de travail :  - Eviter le streaming vidéo (clips ou autres) ou réduire la qualité vidéo au minimum proposé/nécessaire pour la bonne compréhension de la vidéo ;  - Privilégier la radio ou les sites et applications de streaming audio et la fonctionnalité de téléchargement que ces outils proposent si possible.'),
('10027797-09ba-11ee-b881-0cc47a39c2c2', 'eaead655-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Votre structure fait-elle un usage régulier de la visioconférence ? ', 'Désactiver les webcams lors des visioconférences lorsqu\'il n\'est pas pertinent de les garder allumées (lorsque l\'animateur projette une présentation ou qu\'une participation active n\'est pas attendue par exemple). Le but est de trouver le juste équilibre entre convivialité et maîtrise des impacts liés à l\'utilisation des webcams. ', '', ''),
('10027a4b-09ba-11ee-b881-0cc47a39c2c2', 'eaecfa36-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Avez-vous imposé des règles particulières en matière de traitement de texte et autres documents bureautiques (police d\'écriture, tailles et couleurs des caractères, marges, format de documents (Word, PDF, etc.), etc.) ? ', 'Choisir une police d\'écriture économe en encre et accessible, par exemple : \r\n<ul>\r\n      <li>Cambria </li>\r\n      <li>Arial </li>\r\n      <li>Century Gothic</li>\r\n </ul>\r\nPrivilégier les polices dites système ou natives pour les services de communication au public en ligne afin de limiter les requêtes externes.', 'Police d\'écriture', ''),
('4eddae39-09ba-11ee-b881-0cc47a39c2c2', 'eae8bb58-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Une politique de gestion des supports de sauvegarde (répartition des données, choix du type de support selon la nature et la disponibilité attendue, etc.) est-elle définie ? ', 'Lorsque cela est envisageable et approprié, privilégier la technologie dite du Thin Provisioning, aussi appelée Dynamic Provisioning ou allocation fine et dynamique pour la gestion de vos espaces de stockage. \nSe rapprocher du service compétent ou du prestataire pour un accompagnement.', '', 'Lorsque cela est envisageable et approprié, privilégier la technologie dite du Thin Provisioning, aussi appelée Dynamic Provisioning ou allocation fine et dynamique pour la gestion de vos espaces de stockage. Cette technique consiste à ne mobiliser que l\'espace de stockage réellement consommé plutôt que la totalité allouée, évitant ainsi que des ressources ne soient mobilisées pour de l\'espace vide. L\'espace de stockage disponible augmente progressivement, en fonction des besoins et peut être alloué là où il est nécessaire.  A noter que cette technologie présente certaines contraintes dont il est nécessaire de tenir compte avant sa mise en place (nécessité de surveiller la bonne allocation de l\'espace pour éviter d\'en atteindre les limites, d\'être connecté au réseau pour que l\'ajustement s\'opère, risque d\'indisponibilité des données en cas de panne...). Se rapprocher du service compétent ou du prestataire pour un accompagnement.'),
('4eddb6c8-09ba-11ee-b881-0cc47a39c2c2', 'eae8f743-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Favorisez-vous les centres de données qui prennent des engagements environnementaux ? ', 'Vérifier différents indicateurs de performance environnementale, notamment le PUE (Power Usage Effectiveness, indicateur d\'efficacité énergétique), CUE (Carbone Usage Effectiveness, indicateur d\'impact environnemental), WUE (Water Usage Effectiveness, indicateur d\'efficience dans l\'utilisation de l\'eau), REF (Renewable Energy Factor, ratio de l\'utilisation des énergies renouvelables) ou encore COP (Coefficient Of Performance, rendement de la production de froid) des datas centers au sein desquels votre structure stocke ses données.', 'Indicateurs de performance environnementale des centres de données', ''),
('5e0a1b0d-06bd-11ee-b776-0cc47a39c2c0', 'ead873c4-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Votre structure a-t-elle mis en place une gouvernance pour la sobriété numérique (désignation d\'un référent, prise d\'engagements, définition d\'objectifs, mise en place d\'actions...) ', 'Une gouvernance de la démarche vers un numérique plus sobre contient tout ou partie de ces exemples d\'actions : \n- désignation d\'un référent opérationnel/élu, \n- création d\'un comité de pilotage, \n- rédaction d\'un plan d\'action,\n- sélection d\'indicateurs environnementaux et définition d\'objectifs,\n- attribution des critères de suivi et d\'atteinte des objectifs environnementaux,\n- organisation de points de suivi réguliers afin d\'approfondir progressivement les objectifs et/ou d\'élargir les indicateurs pris en compte.', 'Mettre en place une gouvernance', ''),
('5e0a60c3-06bd-11ee-b776-0cc47a39c2c0', 'ead8cae7-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Des missions liées à la sobriété numérique ont-elles été confiées au personnel ? ', 'Intégrer la notion de sobriété numérique aux fiches de poste des agents directement concernés par la démarche et leur attribuer les missions correspondantes (acheteurs publics, agents du service informatique, de la communication...).', 'Missions \"Sobriété numérique\" des agents et autres personnels', ''),
('5e0af297-06bd-11ee-b776-0cc47a39c2c0', 'ead9205e-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Des missions liées à la sobriété numérique ont-elles été confiées aux élus ?', 'Désigner au moins un élu en charge de la sobriété numérique afin que ses enjeux soient portés et pris en compte au sein des organes délibérants de votre structure.', 'Missions \"Sobriété numérique\" des élus', ''),
('5e0b2b43-06bd-11ee-b776-0cc47a39c2c0', 'ead94a96-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Un référent sobriété numérique a-t-il été désigné ?', 'Désigner au moins un référent Sobriété numérique chargé principalement de :  <ul>      <li>diffuser les bonnes pratiques auprès des agents et autres personnels, ainsi que des élus et/ou responsables</li>      <li>d\'alerter et conseiller en lien avec la thématique dans le cadre des projets et missions de votre structure</li>      <li>de piloter la démarche d\'amélioration continue entamée par votre structure</li> </ul>', '', ''),
('5e0b6541-06bd-11ee-b776-0cc47a39c2c0', 'ead9753f-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Un organe de pilotage et/ou groupe de travail a-t-il été mis en place sur le sujet de la sobriété numérique ? ', 'Mettre en place un comité Sobriété numérique afin de piloter la démarche d\'amélioration continue entamée par votre structure de façon homogène et structurée. ', '', 'Mettre en place un comité Sobriété numérique afin de piloter la démarche d\'amélioration continue entamée par votre structure de façon homogène et structurée.  Le comité Sobriété numérique est un organe qui centralise la démarche d\'amélioration continue de la structure. Il est idéalement constitué : \n<ul>      \n    <li>du responsable de la structure ou d\'un représentant de ce dernier</li>      \n    <li>du référent Sobriété numérique</li>      \n    <li>des responsables des principales directions concernées par la démarche (DSI, Achats & marchés publics, Communication...).  Ce comité pourra être constitué d\'acteurs supplémentaires, utiles à la mise en œuvre de la démarche d\'amélioration continue (notamment les prestataires numériques externes)</li> \n</ul>'),
('5e0b9f13-06bd-11ee-b776-0cc47a39c2c0', 'ead99d87-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Votre structure a-t-elle pris des engagements en matière de sobriété numérique ? ', 'Formaliser l\'investissement de votre structure dans la démarche par un acte d\'engagement. ', '', ''),
('5e0bd836-06bd-11ee-b776-0cc47a39c2c0', 'ead9ca87-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Les engagements pris par votre structure ont-ils été rendus publics ?', 'Dans un souci de transparence et d\'exemplarité, il est recommandé de rendre les engagements pris en matière de sobriété numérique publics auprès des administrés et acteurs locaux. Cela est l\'opportunité de mettre en avant la démarche entamée par votre structure.', '', ''),
('5e0c6b0d-06bd-11ee-b776-0cc47a39c2c0', 'eada1203-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Les actions engagées et/ou objectifs fixés par votre structure ont-ils été formalisés sous forme d\'un plan d\'actions ?', 'Définir un plan d\'action afin de prioriser les mesures à mettre en place dans le cadre de la démarche d\'amélioration continue entamée. \nA noter que la loi dite REEN du 15 novembre 2021 introduit des obligations impactant le plan climat-air-énergie (PCAET) pour les collectivités concernées, ainsi que pour les communes de plus 50 000 habitants et les EPCI à fiscalité propre regroupant plus de 50 000 habitants. ', '', 'Définir un plan d\'actions afin de prioriser les mesures à mettre en place dans le cadre de la démarche d\'amélioration continue entamée.  Ce document doit permettre de répartir les responsabilités, d\'estimer les coûts financiers et humains (jours/hommes) et donc le budget et les ressources humaines à allouer, des objectifs concrets et indicateurs de progression/réussite correspondants, ainsi qu\'un délai de mise en œuvre réaliste et adéquat.  Il convient d\'arbitrer entre les actions les plus faciles à mettre en œuvre et celles dont l\'impact sera le plus conséquent pour améliorer l\'indice de maturité de votre structure.  A noter d\'une part, que les EPCI à fiscalité propre regroupant au moins 20 000 habitants sont soumis à l\'obligation d\'adoption d\'un plan climat-air-énergie depuis le 31 décembre 2018 ou dans un délai de deux ans à compter de leur création ou de la date à laquelle ils dépassent le seuil de 20 000 habitants. Ce plan devant notamment contenir un programme d\'actions à réaliser visant, entre autres, à réduire l\'empreinte environnementale du numérique sur leur territoire (sous réserve que l\'élaboration dudit plan n\'ait pas été confiée à un établissement public chargé du schéma de cohérence territoriale).  D\'autre part que, les communes de plus 50 000 habitants et les EPCI à fiscalité propre regroupant plus de 50 000 habitants doivent, au plus tard au 1er janvier 2025, définir une stratégie numérique responsable comprenant un volet sobriété numérique (réduction de l\'empreinte environnementale du numérique) ainsi que les mesures mises en place pour y parvenir. Un programme de travail préalable à l\'élaboration de cette stratégie devant être adopté au plus tard au 1er janvier 2023. '),
('5e0cb729-06bd-11ee-b776-0cc47a39c2c0', 'eada3460-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Avez-vous alloué une part du budget de votre structure à la mise en oeuvre d\'une démarche de sobriété numérique ? ', 'Établir un budget dédié à la démarche pour un numérique plus sobre. Si cette démarche est vouée à générer des économies, elle nécessite certaines dépenses qu\'il est préférable d\'anticiper (financement des sensibilisations/formations, d\'accompagnements spécifiques, achats de logiciels et service...).', 'Définir un budget', ''),
('5e0d053a-06bd-11ee-b776-0cc47a39c2c0', 'eada5694-06bc-11ee-b776-0cc47a39c2c0', 2, 1, 'Des actions de sensibilisation sont-elles menées auprès du personnel sur les enjeux et bonnes pratiques en matière de sobriété numérique ? ', 'Assurer une sensibilisation régulière des agents et autres personnels de votre structure, aux enjeux et bonnes pratiques de la sobriété numérique.\nEn complément de sessions de sensibilisation, diffuser ces enjeux en interne via différents supports physiques et numériques (note d\'organisation, affichage, lettre d\'information interne...).', 'Sensibilisation des agents et autres personnels', ''),
('5e0d4df5-06bd-11ee-b776-0cc47a39c2c0', 'eada8fd0-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Le personnel de votre structure a-t-il été formé aux enjeux et bonnes pratiques en matière de sobriété numérique ? ', 'Former les responsables et/ou agents et autres personnels les plus concernés aux enjeux et bonnes pratiques de la sobriété numérique (DSI/service informatique, achats & marchés publics, communication...).', 'Formation du personnel', ''),
('5e0d96a4-06bd-11ee-b776-0cc47a39c2c0', 'eadacc92-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Des actions de sensibilisation sont-elles menées auprès des élus sur les enjeux et bonnes pratiques en matière de sobriété numérique ? ', 'Assurer une sensibilisation régulière des élus et membres des instances dirigeantes de votre structure, aux enjeux et bonnes pratiques de la sobriété numérique.', 'Sensibilisation des élus et membres des instances dirigeantes', ''),
('5e0ddf42-06bd-11ee-b776-0cc47a39c2c0', 'eadb0117-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Votre structure a-t-elle recours à la location de matériels numériques ? ', 'Privilégier la location d\'équipements numériques à l\'achat. \r\nVeiller toutefois à ce que le prestataire prenne des engagements favorisant effectivement l\'allongement de la durée de vie du matériel loué (matériel écolabellisé et durable, réemployé à l\'issue du contrat...). Il est par exemple possible de fixer un seuil minimum de réemploi du matériel loué à cette fin. ', '', ''),
('5e0e3065-06bd-11ee-b776-0cc47a39c2c0', 'eadb3a87-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Votre structure a-t-elle pris des mesures permettant de favoriser la sobriété numérique dans les achats et locations d\'équipements et services numériques telles que l\'ajout de clauses contractuelles, une prise en compte des écolabels, des indices de réparabilité, d\'éco-conception, d\'achat ou de location d\'équipements issus du réemploi ou de la réutilisation ?', 'Mettre en place des mesures permettant de favoriser la sobriété numérique dans les achats et locations d\'équipements et services numériques (ajout de clauses contractuelles, prise en compte des écolabels, de l\'indice de réparabilité, de l\'éco-conception, achat/location d\'équipements issus du réemploi ou de la réutilisation ...).', '', ''),
('5e0e7cd4-06bd-11ee-b776-0cc47a39c2c0', 'eadb8410-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Votre structure a-t-elle recours au réemploi interne de matériels numériques ? ', 'Diminuer l\'achat d\'outils numériques neufs par le recours au réemploi en interne : étudier les possibilités de réaffecter les outils numériques qui ne répondent plus aux besoins de certains profils utilisateurs vers d\'autres profils aux besoins desquels ils peuvent encore répondre. ', 'Réemploi en interne', ''),
('5e0edb76-06bd-11ee-b776-0cc47a39c2c0', 'eadbba62-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Votre structure a-t-elle recours aux filières externes du reconditionnement, du réemploi et/ou de la réutilisation en matière d\'achats numériques ?', 'Diminuer l\'achat d\'outils numériques neufs par le recours à l\'achat d\'outils numériques issus d\'une filière du réemploi externe ou reconditionnés. \nRespecter, a minima, les seuils fixés par le décret du 9 mars 2021 pris pour l\'application de la disposition correspondante de la loi AGEC.', 'Achat d\'équipements numériques issus du reconditionnement, du réemploi et/ou de la réutilisation', 'Diminuer l\'achat d\'outils numériques neufs par l\'achat d\'outils numériques issus d\'une filière du réemploi externe ou reconditionné. Respecter, a minima, les seuils fixés par le décret en vigueur pris pour l\'application de la disposition correspondante de la loi AGEC (article 58) : I. - À compter du 1ᵉʳ janvier 2021, les biens acquis annuellement par les services de l\'État ainsi que par les collectivités territoriales et leurs groupements sont issus du réemploi ou de la réutilisation ou intègrent des matières recyclées dans des proportions de 20 % à 100 % selon le type de produit. II. - En cas de contrainte opérationnelle liée à la défense nationale ou de contrainte technique significative liée à la nature de la commande publique, le pouvoir adjudicateur n\'est pas soumis à l\'obligation prévue au I [...]. À noter que ce même texte prévoit la déclaration de la part des dépenses réalisées pour l\'acquisition de biens issus du réemploi ou de la réutilisation ou intégrant des matières recyclées.  Extrait du décret : Produis ou catégories de produits : Machines, matériel et fourniture informatique et de bureau, excepté les meubles et logiciels ; Terminaux informatiques ; Ordinateurs portables ; Ordinateur de bureau ; Accessoires informatiques ; Photocopieurs et matériel d\'impression offset ; Pièces et accessoires de photocopieurs ; Téléphones mobiles ; Téléphones fixes ; % issu du réemploi ou de la réutilisation ou intégrant des matières recyclées : 20% Dont % issu du réemploi ou de la réutilisation : 20%.\n\nIl est à noter que les pourcentages ci-dessus s\'appliquent de 2024 à 2027. À partir de 2027, les taux seront de 25 % puis 30 % à compter de 2030.'),
('5e0f3a5c-06bd-11ee-b776-0cc47a39c2c0', 'eadbf343-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Des clauses environnementales sont-elles inclues dans les appels d\'offre et contrats conclus hors marché pour l\'achats d\'équipements numériques ? ', 'Intégrer des clauses environnementales dans les appels d\'offre et contrats conclus hors marché. ', 'Clauses environnementales', 'Intégrer des clauses environnementales dans les appels d\'offre et contrats conclus hors marché.  Pour les solutions logicielles et systèmes d\'exploitation : des exigences doivent être posées concernant la séparation des mises à jour des sécurité de celles dites de confort, l\'assurance d\'une continuité de ces mises à jour ainsi que du support technique durant un laps de temps suffisamment long, ou encore la nécessité que ces mises à jour n\'entrainent pas une hausse trop importante des prérequis techniques de nature à favoriser l\'obsolescence logicielle et ainsi une réduction de la durée de vie des équipements numériques.  Pour les biens et notamment le matériel numérique : des exigences doivent être posées concernant leur durée de vie, leur réparabilité voire leur durabilité (notamment facilité de démontage, disponibilité des pièces détachées...), les écolabels qu\'ils doivent présenter ou encore la gestion de leur fin de vie (reprise par le fournisseur/distributeur, prise en charge par un éco-organisme agréé...).  Dans tous les cas, l\'éco-conception doit être posée comme un prérequis indispensable.   A noter que des dispositions concernant les marchés publics doivent entrer en vigueur suite à l\'adoption de la loi Climat et résilience, suivant une date fixée par un décret en cours d\'étude et au plus tard le 22 août 2026. Celles-ci viendront modifier le code de la commande publique afin de généraliser la prise en compte de considérations relatives à l\'environnement en la matière tant dans les spécifications techniques que les conditions d\'exécution, mais aussi pour l\'attribution du marché.  L\'article 35 de la loi Climat et résilience introduit notamment l\'obligation pour les acheteurs et les autorités concédantes, de retenir au moins un critère d\'attribution prenant en compte les caractéristiques environnementales de l\'offre.  Le législateur a fait le choix de ne pas énumérer les caractéristiques environnementales qui doivent être spécifiquement prises en compte en tant que critère. En effet, la formulation retenue demeure large afin de laisser une certaine souplesse aux acheteurs et aux autorités concédantes. Il leur revient ainsi de déterminer le critère qui leur paraît le plus approprié au regard des caractéristiques du contrat concerné.  En pratique, cette évolution interdit le recours au critère unique du prix. Ainsi, si l\'acheteur fait le choix de ne retenir qu\'un seul critère de sélection, seul le critère unique du coût global intégrant nécessairement des considérations environnementales pourra désormais être retenu.   Pour aller plus loin : envisager la mise en place d\'un plan de progrès avec le titulaire/cocontractant afin d\'engager une démarche d\'amélioration continue conjointe vers une numérique plus sobre dans le cadre de la prestation assurée. '),
('5e10ccab-06bd-11ee-b776-0cc47a39c2c0', 'eadc2bc8-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Tenez-vous compte des écolabels et autres référentiels dans le cadre de vos achats numériques (Energie Star, 80 Plus, EPEAT, Blue Angel...) ? ', 'Privilégier l\'achat d\'équipements numériques écolabellisés, qui répondent à des normes reconnues et/certifiés (EPEAT, TCO, Energy Star, 80 Plus, Blue Angel...). ', 'Écolabels et autres référentiels pour les équipements numériques', 'Privilégier l\'achat d\'équipements numériques écolabellisés, qui répondent à des normes reconnues et/ou certifiés (EPEAT, TCO, Energy Star, 80 Plus, Blue Angel...).   En cas de référence à des labels spécifiques dans le cadre d\'un achat, se référer aux articles R2111-12 à R2111-17 du code de la commande publique (modalités d\'utilisation de labels). Se référer également à la Section 4 Les labels (voir pages 22 et suivantes) du Guide des achats numériques responsables pour connaître les conditions permettant à l\'acheteur public d\'imposer à l\'opérateur économique qu\'il détienne un label particulier dans le cadre d\'un marché public.'),
('5e1116b4-06bd-11ee-b776-0cc47a39c2c0', 'eadc66b4-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Tenez-vous compte de l\'indice de réparabilité dans le cadre de vos achats pour les outils numériques qui en disposent ? ', 'Tenir compte de l\'indice de réparabilité pour les achats d\'outils numériques. À noter que sa prise en compte devient obligatoire à compter du 1er janvier 2023. Son successeur, l\'indice de durabilité, n\'est applicable (au 1er janvier 2025) qu\'aux téléviseurs et machines à laver, sans qu\'une date pour les autres produits (ordinateurs, téléphones) ne soit connue.', 'Indice de réparabilité', ''),
('5e11627e-06bd-11ee-b776-0cc47a39c2c0', 'eadc9d71-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Votre structure dispose-t-elle d\'une politique d\'achat et de renouvellement des outils numériques définie ?', 'Mettre en place une politique d\'achats intégrant les principes de la sobriété numérique (critères techniques exigés (puissance, fiabilité, durabilité, ...), la politique d\'équipement associée (faire une étude des besoins utilisateurs : quel besoin dans quelle situation), règles d\'achat sobriété numérique sous forme de critères environnementaux ou d\'écoconditionnalités...). ', 'Politique d\'achats', ''),
('5e11ca07-06bd-11ee-b776-0cc47a39c2c0', 'eadcd379-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Votre structure a-t-elle pris des mesures permettant de favoriser la sobriété numérique dans les achats pour l\'impression telles que le choix du papier, de l\'encre et des toners ?', 'Mettre en place des mesures permettant de favoriser la sobriété numérique dans les achats pour l\'impression (choix du papier, de l\'encre et des toners...). ', '', ''),
('5e123aa5-06bd-11ee-b776-0cc47a39c2c0', 'eade5b21-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Tenez-vous compte des écolabels dans le cadre de vos achats de papiers (FSC, PEFC, Blue Angel......) ', 'Privilégier l\'achat de papiers écolabellisés (Blue Angel ou FSC par exemple) et à faible grammage, dans le respect des articles R2111-12 à R2111-17 du code de la commande publique (modalités d\'utilisation de labels). ', 'Écolabels pour les achats d\'impression', ''),
('5e129146-06bd-11ee-b776-0cc47a39c2c0', 'eade9913-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Utilisez-vous du papier recyclé pour vos impressions ?', 'Privilégier l\'achat de papiers recyclés (voir les papiers labellisés Blue Angel ou FSC recyclé notamment) et à faible grammage.\n\nRespecter, a minima, les seuils fixés par le décret en vigueur pris pour l\'application de la disposition correspondante de la loi AGEC.', 'Papier recyclé', 'Privilégier l\'achat de papiers recyclés (voir les papiers labellisés Blue Angel ou FSC recyclé notamment) et à faible grammage. En cas de référence à des labels spécifiques, se référer aux articles\n R2111-12 à R2111-17 du code de la commande publique (modalités d\'utilisation de labels).\n\nRespecter, a minima, les seuils fixés par le décret en vigueur pris pour l\'application de la disposition correspondante de la loi AGEC (article 58) : \"I. - À compter du 1er janvier 2021, les biens\n acquis annuellement par les services de l\'État ainsi que par les collectivités territoriales et leurs groupements, sont issus du réemploi ou de la réutilisation ou intègrent des matières recyclées dans des proportions de 20 % à 100 % selon le type de produit.\n\nII. - En cas de contrainte opérationnelle liée à la défense nationale ou de contrainte technique significative liée à la nature de la commande publique, le pouvoir adjudicateur n\'est pas soumis à l\'obligation\n prévue au I [...].\"\n\nExtrait du décret, exigences 2024 :\n\nProduis ou catégories de produits : Papier d\'impression ; Papier pour photocopie ;\n\n% issu du réemploi ou de la réutilisation ou intégrant des matières recyclées : 40%\n\nDont % issu du réemploi ou de la réutilisation : 0%'),
('5e12e526-06bd-11ee-b776-0cc47a39c2c0', 'eadec861-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Avez-vous adopté des pratiques d\'achat en matière de toner et cartouches d\'encre sobres (recharge, achat de toner/cartouches recyclés...) ? ', 'Modifier les pratiques d\'achat de cartouches et toner :\n\n- Recharger les cartouches / toners ;\n- Acheter des cartouches / toners recyclés longue durée.\n\nRespecter, a minima, les seuils fixés par le décret en vigueur pris pour l\'application de la disposition correspondante de la loi AGEC.', 'Toners et cartouches d\'encre', 'Modifier les pratiques d\'achat de cartouches et toner :\n\n- Recharger les cartouches / toners ;\n- Acheter des cartouches / toners recyclés longue durée.\n\nRespecter, a minima, les seuils fixés par le décret en vigueur pris pour l\'application de la disposition correspondante de la loi AGEC (article 58) : \"I. - À compter du 1er janvier 2021, les biens\n acquis annuellement par les services de l\'État ainsi que par les collectivités territoriales et leurs groupements, sont issus du réemploi ou de la réutilisation ou intègrent des matières recyclées dans des proportions de 20 % à 100 % selon le type de produit.\n\nII. - En cas de contrainte opérationnelle liée à la défense nationale ou de contrainte technique significative liée à la nature de la commande publique, le pouvoir adjudicateur n\'est pas soumis à l\'obligation\n prévue au I [...].\"\n\nExtrait du décret, exigences 2024 :\n\nProduis ou catégories de produits : Cartouches de toner ; Cartouches d\'encre ;\n\n% issu du réemploi ou de la réutilisation ou intégrant des matières recyclées : 20%\n\nDont % issu du réemploi ou de la réutilisation : 20%'),
('5e13362e-06bd-11ee-b776-0cc47a39c2c0', 'eadefc43-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Faîtes-vous appel à des fournisseurs d\'énergie dite « verte »/renouvelable ? ', 'Alimenter le système d\'information (SI) de préférence avec de l\'énergie renouvelable ou dite \"décarbonée\" ou encore \"verte\".', 'Origine de l\'énergie alimentant le système d\'information', ''),
('5e13858c-06bd-11ee-b776-0cc47a39c2c0', 'eadf40b1-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Disposez-vous d\'un inventaire du parc numérique de votre structure (postes informatiques et écrans, téléphones, tablettes, supports de sauvegardes amovibles, vidéoprojecteurs...) ? ', 'Tenir un inventaire du parc numérique de votre structure (postes informatiques et écrans, téléphones, tablettes, supports de sauvegardes amovibles, vidéoprojecteurs...). Celui-ci est un élément indispensable de la cartographie de son système d\'information (SI).', 'Inventaire du parc numérique', ''),
('5e13d5b9-06bd-11ee-b776-0cc47a39c2c0', 'eadf7764-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Avez-vous documenté l\'architecture de votre système d\'information (serveurs et autres matériels informatiques, infrastructures, applicatif, etc.) ? ', 'Documenter l\'architecture de votre SI (serveurs, VM, applicatif, etc.). Se rapprocher du prestataire informatique le cas échéant pour un accompagnement.', 'Cartographie du système d\'information', ''),
('5e142565-06bd-11ee-b776-0cc47a39c2c0', 'eadfd1c0-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'L\'architecture de votre système d\'information est-elle optimisée par rapport aux besoins de votre structure ? ', 'Effectuer une revue de l\'architecture du système d\'information (SI) afin d\'identifier les ressources potentiellement inutilisées (serveurs, espaces de stockage...) et réétudier leur déploiement en conséquence. Privilégier une architecture modulaire et frugale s\'adaptant aux besoins de votre structure.', 'Rationalisation du système d\'information', ''),
('5e147765-06bd-11ee-b776-0cc47a39c2c0', 'eae0041e-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Quelle est la durée de vie moyenne des postes informatiques de votre structure ? ', 'Allonger la durée de vie des postes informatiques.', 'Allongement de la durée de vie des équipements numériques', ''),
('5e14be3b-06bd-11ee-b776-0cc47a39c2c0', 'eae03ede-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Quelle est la durée de vie moyenne des copieurs/imprimantes de votre structure ? ', 'Allonger la durée de vie des copieurs/imprimantes.', 'Allongement de la durée de vie des copieurs et imprimantes', ''),
('5e15069b-06bd-11ee-b776-0cc47a39c2c0', 'eae07ac9-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Quelle est la durée de vie moyenne des téléphones de votre structure ?', 'Allonger la durée de vie des téléphones.', 'Allongement de la durée de vie des téléphones', ''),
('5e154e7f-06bd-11ee-b776-0cc47a39c2c0', 'eae0b739-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Assurez-vous la traçabilité des attributions et besoins en outils informatiques en interne ? ', 'Assurer le suivi des attributions d\'équipements numériques : \n-        Mettre en place une documentation assurant la traçabilité des attributions et restitutions d\'outils ; \n-        Effectuer une revue annuelle des besoins et attributions ; \n-        Inviter les utilisateurs à restituer le matériel non-utilisé pour réaffectation selon les besoins internes.', 'Suivi des attributions d\'équipements numériques', ''),
('5e1597fd-06bd-11ee-b776-0cc47a39c2c0', 'eae0efce-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Connaissez-vous le taux moyen d\'équipement numérique/utilisateur de votre structure ? ', 'Documenter le taux moyen d\'équipement numérique/utilisateur afin d\'en suivre l\'évolution.', 'Taux moyens d\'équipement numérique/utilisateur', ''),
('5e15dfe9-06bd-11ee-b776-0cc47a39c2c0', 'eae128ef-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Quels sont le nombre et la taille moyens des écrans mis à disposition des utilisateurs ?', 'Réduire le nombre et la taille des écrans au strict nécessaire.', 'Écrans mis à disposition', ''),
('5e16c38b-06bd-11ee-b776-0cc47a39c2c0', 'eae2025d-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Combien de téléphones professionnels (fixes et mobiles) sont-ils mis à disposition des utilisateurs de votre structure et de quels types (téléphones simples, reconditionnés, en réemploi, smartphone...) ? ', 'Limiter le nombre de terminaux de téléphonie.', 'Limitation du nombre de téléphones', ''),
('5e1718ce-06bd-11ee-b776-0cc47a39c2c0', 'eae246b3-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'L\'utilisation des outils professionnels à des fins personnelles et/ou l\'utilisation d\'outils personnels à des fins professionnelles est-elle autorisée ?', 'Favoriser le recours à la double carte SIM afin de réduire les doublons téléphones portables professionnel/personnel.', 'Double carte SIM', ''),
('5e176a1a-06bd-11ee-b776-0cc47a39c2c0', 'eae2877c-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Avez-vous mis en place des consignes et pratiques de nature à allonger la durée de vie de vos équipements numériques (favoriser la réparation avant le remplacement, dissocier le remplacement des équipements selon les besoins, maintenance...) ?', 'Mettre en place une politique de gestion du parc numérique intégrant les principes de la sobriété numérique :\n- identification des besoins utilisateurs par profils-types, \n- cycle de vie des différents outils et notamment le potentiel réemploi interne ou externe de matériels en fin de vie, \n- durée d’amortissement,\n- méthodologie choisie pour sa réparabilité (interne ou externalisation), son impact environnemental (GES ou ACV), ses bonnes pratiques d’usage (extinction, veille, allumage, etc...).', 'Politique de gestion du parc numérique', ''),
('5e17d587-06bd-11ee-b776-0cc47a39c2c0', 'eae2c4d3-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Mettez-vous à disposition des protections pour les équipements numériques fournis (sacoche, coque...) ?', 'Afin d\'allonger la durée de vie des équipements numériques, mettre en place toutes les protections physiques et logicielles adéquates (coque et écran de protection, étui ou sacoche de rangement, etc.). \r\nEn parallèle, il convient d\'inviter les utilisateurs à adopter les bons gestes pour prendre soin de leurs outils, notamment :\r\n<ul>\r\n            <li>Ne pas laisser les outils numériques au soleil ou près d\'une source de chaleur</li>\r\n            <li>Les installer sur des surfaces plate et rigide afin de ne pas gêner la ventilation</li>\r\n<li>Les dépoussiérer régulièrement avec du matériel adapté</li>\r\n<li>Respecter les consignes du fabricant sur la charge de la batterie. À défaut, consulter le fournisseur et le service compétent pour les connaître</li>\r\n        </ul>', 'Protection des équipements numériques', ''),
('5e18248f-06bd-11ee-b776-0cc47a39c2c0', 'eae300f3-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Régulez-vous les attributions d\'équipements numériques en fonction des besoins réels des utilisateurs ?', 'Il convient, d\'une part, de ne renouveler les équipements numériques que lorsque cela est réellement nécessaire. Autrement dit, lorsque l\'équipement n\'est plus fonctionnel, entrave la bonne réalisation des missions de l\'utilisateur ou constitue un risque pour la sécurité du système d\'information (SI). \r\nD\'autre part, l\'équipement attribué doit être adapté aux besoins réels de l\'utilisateur (type, taille, puissance, etc.). ', 'Dotations adaptées aux besoins des utilisateurs', ''),
('5e186c49-06bd-11ee-b776-0cc47a39c2c0', 'eae33bb4-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Quelle est la durée de dotation moyenne pour les principaux équipements mis à disposition des utilisateurs (ordinateurs fixes ou mobiles, écrans et autres accessoires, téléphones mobiles et tablettes) ? ', 'Documenter et allonger la durée de dotation des équipements numériques. ', 'Durée de dotation des équipements numériques', ''),
('5e18ad87-06bd-11ee-b776-0cc47a39c2c0', 'eae37420-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'La configuration des équipements numériques est-elle adaptée aux différents profils utilisateur ? ', 'Adapter la configuration des équipements numériques au juste nécessaire des usages métier.', 'Configuration des équipements adaptées aux besoins utilisateur', ''),
('5e18f0ef-06bd-11ee-b776-0cc47a39c2c0', 'eae3aeb4-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Le renouvellement des unités centrales est-il dissocié de celui des écrans et autres accessoires ? ', 'Dissocier le renouvellement des unités centrales de celui des écrans et autres accessoires (clavier, etc.). ', 'Renouvellement dissocié des équipements numériques', ''),
('5e193f00-06bd-11ee-b776-0cc47a39c2c0', 'eae3ecd0-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'La mise à niveau notamment par l\'ajout ou le remplacement de composants est-elle privilégiée au renouvellement des outils numériques ? ', 'Mettre à niveau les équipements plutôt que de les remplacer (augmentation de la puissance, de la capacité de stockage...). ', 'Privilégier la mise à niveau des équipements numériques', 'Mettre à niveau les équipements plutôt que de les remplacer (augmentation de la puissance, de la capacité de stockage...).  Selon L\'Institut du Numérique Responsable (INR) : Sur les plans économique et environnemental, il est plus intéressant de doper un équipement vieillissant que de le remplacer par un équipement neuf. Le simple fait d\'ajouter de la capacité mémoire vive (RAM) suffit généralement à allonger la durée de vie d\'un poste de travail de 1 à 2 ans.  Pour les ordinateurs portables, on peut compléter la démarche en remplaçant le disque dur par un SSD.  Pour s\'assurer de pouvoir mettre en œuvre cette bonne pratique, il peut être judicieux d\'ajouter quelques exigences techniques lors de l\'appel d\'offre, notamment :  <ul>             <li>la facilité de démontage et la possibilité d\'accéder aux composants clés</li>             <li>et la possibilité d\'étendre la capacité de la mémoire vive et de remplacer les autres composants clés</li>         </ul>'),
('5e1988a3-06bd-11ee-b776-0cc47a39c2c0', 'eae42705-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Des composants disponibles en interne sont-ils utilisés pour la mise à niveau des équipements numériques (issus d\'autres équipements en fin de vie par exemple) ? ', 'Pour la mise à niveau des équipements numériques, réutiliser si possible les composants encore fonctionnels des équipements numériques en fin de vie (barrettes de mémoire notamment).', 'Réutilisation de composants disponibles', ''),
('5e19f23e-06bd-11ee-b776-0cc47a39c2c0', 'eae46319-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Réparez-vous les équipements numériques en cas de panne/casse ?', 'Toujours considérer la réparation d\'un équipement numérique avant toute autre option (réemploi, réutilisation, recyclage...).', 'Réparation des équipements numériques', ''),
('5e1a440e-06bd-11ee-b776-0cc47a39c2c0', 'eae4a1db-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'La maintenance informatique (matériel et logiciels) est-elle assurée de façon régulière ? ', 'Assurer une maintenance régulière des équipements numériques pour en prolonger la durée de vie. \nSe rapprocher du service interne ou prestataire en charge de la maintenance pour un accompagnement.', 'Maintenance régulière des équipements numériques', 'Assurer une maintenance régulière des équipements numériques pour en prolonger la durée de vie.  Des actions simples peuvent être mises en place :  <ul>             <li>installer une protection payante contre les virus et les malwares</li>             <li>mettre à jour régulièrement le système d\'exploitation</li> <li>rebooter occasionnellement les machines</li> <li>vider les fichiers temporaires : navigateur, système, etc.</li> <li>nettoyer la base de registre</li> <li>défragmenter le disque dur et la base de registre</li> <li>supprimer certains programmes du démarrage</li> <li>etc</li>         </ul>  Se rapprocher du service interne ou prestataire en charge de la maintenance pour un accompagnement.'),
('5e1a8fcc-06bd-11ee-b776-0cc47a39c2c0', 'eae4daaa-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Utilisez-vous des solutions logicielles et systèmes d\'exploitation libres ?', 'Lorsque cela est possible, privilégier l\'utilisation de solutions logicielles et systèmes d\'exploitation libres.', 'Favoriser le libre', '');
INSERT INTO `recommandation` (`id`, `question_id`, `level_id`, `status_id`, `title`, `body`, `short_title`, `details`) VALUES
('5e1af44e-06bd-11ee-b776-0cc47a39c2c0', 'eae51626-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Qu\'advient-il du matériel encore fonctionnel remplacé ?', 'Concernant le réemploi en externe : \nPour les équipements numériques (écrans, moniteurs et équipements comprenant des écrans d\'une surface supérieure à 100 cm2, ainsi que les petits équipements informatiques et de télécommunications) encore fonctionnels (moins de 10 ans), à défaut d\'un réemploi en interne (réaffectation à un autre utilisateur), ils doivent rejoindre les filières du réemploi et de la réutilisation. Respecter a minima les quotas réglementaires :\n<ul>\n            <li>Pour l\'année 2023, 25% des équipements numériques réformés orientés vers le réemploi et la réutilisation</li>\n            <li>Pour l\'année 2024, 35% des équipements numériques réformés orientés vers le réemploi et la réutilisation</li>\n<li>À partir de 2025, 50% des équipements numériques réformés orientés vers le réemploi et la réutilisation</li>\n        </ul>\nS\'agissant donc de vendre ou donner le bien, cela constitue un acte de cession qui peut être à titre gratuit, ou à titre onéreux. Il doit être établit selon les selon les conditions applicables en la matière. Il est dans tous les cas conseillé d\'établir une convention de cession ou un acte de vente à titre gratuit ou onéreux qui matérialise le transfert de propriété et par conséquent de responsabilité du bien. ', 'Réemploi en externe', 'Concernant le réemploi en externe :  Pour les équipements numériques (écrans, moniteurs et équipements comprenant des écrans d\'une surface supérieure à 100 cm2, ainsi que les petits équipements informatiques et de télécommunications) encore fonctionnels (moins de 10 ans), à défaut d\'un réemploi en interne (réaffectation à un autre utilisateur), ils doivent rejoindre les filières du réemploi et de la réutilisation. Respecter a minima les quotas réglementaires :  <ul>             <li>Pour l\'année 2023, 25% des équipements numériques réformés orientés vers le réemploi et la réutilisation</li>             <li>Pour l\'année 2024, 35% des équipements numériques réformés orientés vers le réemploi et la réutilisation</li> <li>À partir de 2025, 50% des équipements numériques réformés orientés vers le réemploi et la réutilisation</li>         </ul> S\'agissant donc de vendre ou donner le bien, cela constitue un acte de cession qui peut être à titre gratuit (selon les conditions applicables pour les organismes publics), ou à titre onéreux :  La cession à titre gratuit, le don, est très encadrée pour les personnes publiques, en effet elle ne peut être qu\'à destination du personnel ou d\'une association (pour le détail, voir l\'article L3212-3 du Code général de la propriété des personnes publiques, renvoyant à l\'article précédent, L3212-2 concernant les biens de l\'État et de ses établissements publics). Sachant que le seuil de la valeur résiduelle unitaire du bien à céder a été fixée par décret à 300 euros (Décret n° 2009-1751 du 17/01/2019). Si la valeur du bien est supérieure à 300 euros, il doit faire l\'objet d\'une vente dans le respect des règles de la concurrence.  Il est dans tous les cas conseillé d\'établir une convention de cession ou un acte de vente à titre gratuit ou onéreux qui matérialise le transfert de propriété et par conséquent de responsabilité du bien. Cet acte permet d\'attester de la sortie du parc d\'équipements sans que celui-ci ne soit suivi comme déchet. Charge au nouveau propriétaire de gérer dans le futur sa fin d\'usage par un nouveau don ou par l\'abandon en déchets. En cas de don, il devra aussi mentionner l\'engagement du personnel ou du tiers à ne pas revendre l\'équipement ou l\'engagement de l\'association à n\'utiliser l\'équipement qui lui est cédé que pour l\'objet prévu par ses statuts, à l\'exclusion de tout autre, et notamment qu\'elle ne peut pas revendre l\'équipement. A noter toutefois l\'exception introduite par la loi 3DS du 21 février 2022 pour les associations reconnues d\'utilité publique ou d\'intérêt général : ces associations peuvent procéder à la cession, à un prix solidaire ne pouvant dépasser un seuil défini par décret, des biens ainsi alloués à destination de personnes en situation de précarité ou à des associations oeuvrant en faveur de telles personnes. '),
('5e1b49da-06bd-11ee-b776-0cc47a39c2c0', 'eae552de-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Avez-vous mis en place des consignes et pratiques de nature à réduire la consommation d\'énergie de votre parc informatique (mise en veille, extinction des équipements, paramétrage de la luminosité, suivi des consommations...) ? ', 'Sauf contrainte technique ou organisationnelle, déconnecter ou débrancher tous les outils numériques en fin de journée. Le faire a minima avant les week-ends et absences prolongées. \nCette opération peut être facilitée par l\'installation de multiprises, voire la mise en place d\'un logiciel de power management. Les bénéfices sont la réduction de la consommation électrique de la struture.', 'Déconnexion des outils', ''),
('5e1b9e62-06bd-11ee-b776-0cc47a39c2c0', 'eae58bfd-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Les équipements numériques sont-ils paramétrés de manière à réduire leur consommation d\'énergie (mode économie d\'énergie par défaut, suppression d\'applications énergivores, paramétrage par défaut de la luminosité, etc.) ?', 'Mettre en place, par défaut, les paramétrages favorisant une réduction de la consommation d\'énergie des outils numériques (options d\'alimentation, mise en veille automatique, etc.).', 'Paramètres d\'économie d\'énergie', 'Mettre en place, par défaut, les paramétrages favorisant une réduction de la consommation d\'énergie des outils numériques :  <ul>             <li>Procéder au paramétrage des options d\'alimentation selon le profil utilisateur en favorisant autant que possible l\'économie d\'énergie</li>             <li>Paramétrer une mise en veille rapide. Plus le temps d\'inactivité avant mise en veille et court, mieux cela est en termes de sobriété. Couplé au verrouillage automatique des postes, cela contribue par ailleurs à la sécurité du système d\'information (SI) et données personnelles qu\'il contient</li>         </ul>  En parallèle, sensibiliser les utilisateurs qui laissent leurs équipements numériques, et notamment leur poste informatique, allumés inutilement. <ul>             <li>Réduire la luminosité des écrans au strict nécessaire pour le confort visuel de l\'utilisateur</li>             <li>Désactiver le lancement automatique des programmes qui n\'ont pas besoin de l\'être à l\'allumage des terminaux</li>         </ul>'),
('5e1c1153-06bd-11ee-b776-0cc47a39c2c0', 'eae5ca98-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Avez-vous mis en place une politique d\'économie d\'énergie de votre système d\'information (SI) ? ', 'Définir une politique d\'économie d\'énergie de votre système d\'information (SI).', 'Politique d\'économie d\'énergie', ''),
('5e1c617d-06bd-11ee-b776-0cc47a39c2c0', 'eae6072c-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Avez-vous mis en place des outils de mesure de la consommation d\'énergie de votre parc informatique ? ', 'Mettre en place des outils de mesure/monitoring de la consommation d\'énergie de votre parc numérique (postes informatiques, sites internet, applications...).', 'Outils de mesure de la consommation d\'énergie', ''),
('5e1cea54-06bd-11ee-b776-0cc47a39c2c0', 'eae642ee-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Utilisez-vous un logiciel de power management ? ', 'Utiliser un logiciel de power management qui étudie et minimise les consommations énergétiques.', 'Logiciel de power management', ''),
('5e1d42d4-06bd-11ee-b776-0cc47a39c2c0', 'eae67ca7-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Connaissez-vous la part du système d\'information (SI) dans la consommation énergétique totale de votre structure ? ', 'Documenter la part représentée par le SI dans la consommation énergétique totale de votre structure. ', 'Consommation d\'énergie du SI', ''),
('5e1d9f54-06bd-11ee-b776-0cc47a39c2c0', 'eae6b4b3-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Avez-vous mis en place des outils de mesure de l\'impact environnemental de votre parc numérique ?', 'Mettre en place des outils de mesure/monitoring et/ou évaluer l\'impact environnemental du parc numérique (postes informatiques, sites internet, applications...).', 'Outils de mesure de l\'impact environnemental', ''),
('5e1e096e-06bd-11ee-b776-0cc47a39c2c0', 'eae6f0c0-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Avez-vous mis en place des paramétrages favorisant la sobriété numérique en matière d\'impression de documents (impression en noir et blanc, recto/verso, protégée...) ? ', 'Modifier les paramètres d\'impression par défaut des postes informatiques et imprimantes (mode éco, noir et blanc, etc.).', 'Paramètres d\'impression par défaut', 'Modifier les paramètres d\'impression par défaut des postes informatiques et imprimantes :  - Paramétrer par défaut les imprimantes en mode éco ; - Paramétrer par défaut l\'impression en noir et blanc et recto/verso ;  - Privilégier l\'impression en niveaux de gris et optimiser l\'utilisation d\'encre ;  - Paramétrer le mode « Suppression des pages blanches » en standard ;  - Mettre en place le mode épreuve pour limiter les impressions « ratées » ;  - Mettre en place un logiciel de suivi des impressions pour étudier et rationaliser les pratiques ;  - Mettre en place l\'impression sécurisée (consistant à ne libérer l\'impression du document que si l\'agent s\'identifie et indique son code confidentiel).'),
('5e1e6525-06bd-11ee-b776-0cc47a39c2c0', 'eae72d87-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Connaissez-vous les obligations de votre structure en matière de traitement des DEEE ? ', 'Organiser la collecte et assurer le recyclage des DEEE : \n-        Ne considérer le recyclage qu\'en dernier ressort et étudier la possibilité de réparer, réemployer ou réutiliser les EEE ainsi que leurs déchets collectés : à noter que les équipements informatiques fonctionnels de moins de 10 ans doivent désormais rejoindre les filières du réemploi et de la réutilisation (cf. Décret n° 2023-266 du 12 avril 2023 fixant les objectifs et modalités de réemploi et de réutilisation des matériels informatiques réformés par l\'Etat et les collectivités territoriales) ; \n-        Mettre en place de façon systématique et optimiser le tri des DEEE ; \n-        Choisir un éco-organisme agréé pour leur prise en charge ; \n-        Assurer une traçabilité des DEEE et notamment obtenir des attestations de bon traitement des prestataires externes chargés de leur reprise.', 'Collecte des DEEE', ''),
('5e1eb9c5-06bd-11ee-b776-0cc47a39c2c0', 'eae791b1-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Une politique de gestion des DEEE est-elle en place (postes informatiques, téléphones, imprimantes/scanners, cartouches d\'encre et toner...) ? ', 'Organiser la collecte et assurer le recyclage des DEEE : \n<ul>\n    <li>Ne considérer le recyclage qu\'en dernier ressort et étudier la possibilité de réparer, réemployer ou réutiliser les EEE ainsi que leurs déchets collectés : à noter que les équipements informatiques fonctionnels de moins de 10 ans doivent désormais rejoindre les filières du réemploi et de la réutilisation (précisions à venir par l\'adoption d\'un décret d\'application qui précisera les modalités, les quantités et le calendrier)</li>\n    <li>Mettre en place de façon systématique et optimiser le tri des DEEE</li>\n    <li>Choisir un éco-organisme agréé pour leur prise en charge</li>\n    <li>Assurer une traçabilité des DEEE et notamment obtenir des attestations de bon traitement des prestataires externes chargés de leur reprise.</li>\n</ul>', 'Collecte des DEEE', ''),
('5e1f0544-06bd-11ee-b776-0cc47a39c2c0', 'eae7cc9e-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Pourriez-vous estimer le volume de vos DEEE sur une année ? ', 'Documenter le volume de vos DEEE sur une année afin d\'en suivre l\'évolution. ', 'Volume des DEEE', ''),
('5e1f6813-06bd-11ee-b776-0cc47a39c2c0', 'eae80242-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Selon quelles modalités les outils numériques sont-ils reliés au réseau internet ?', 'Privilégier la connexion réseau en filaire ou via Wi-Fi à défaut. L\'utilisation des réseaux mobiles (2G/3G/4G/5G) doit être réduite au strict minimum (par exemple en désactivant le transfert de données mobiles une fois la tâche accomplie).', '', ''),
('5e1fc3ee-06bd-11ee-b776-0cc47a39c2c0', 'eae84289-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Une politique de gestion des données numériques (suppression des doublons, mutualisation des données, durée de conservation limitée, archivage intermédiaire et définitif, système d\'archivage électronique (SAE), etc.) est-elle en place ?', 'Mettre en place une politique de gestion de la donnée afin d\'en limiter la quantité stockée sur les supports dédiés (gestion de la collecte, de la conservation, de l\'archivage des données, etc.). \nVeiller à tenir compte des règles propres à l\'archivage public dans ce processus. Se rapprocher du service des archives compétent, ainsi que des archives départementales pour un accompagnement. \nIl convient en outre d\'associer le délégué à la protection des données (DPO) de votre structure, s\'il y en a un, pour les questions relatives aux données personnelles. ', '', 'Mettre en place une politique de gestion de la donnée afin d\'en limiter la quantité stockée sur les supports dédiés : <ul>     <li>Appliquer le principe de pertinence et de minimisation des données collectées dans l\'ensemble des missions de la structure.  Envisager la mutualisation des données afin de prévenir la collecte et le stockage en double lorsque cela est pertinent et dans le respect des règles relatives à la protection des données personnelles le cas échéant (sécurité des données, information des personnes voire obtention préalable du consentement si nécessaire).  Il convient d\'associer le délégué à la protection des données (DPO) de votre structure, s\'il y en a un, pour les questions relatives aux données personnelles</li>     <li>Appliquer le principe de durée de conservation limitée des données dans l\'ensemble des missions de la structure et inviter les utilisateurs à trier leurs données numériques régulièrement afin de ne pas conserver des données qui ne sont plus pertinentes.  Veiller toutefois à tenir compte des règles propres à l\'archivage public dans ce processus, et notamment des Durée d\'Utilité Administrative (DUA) applicables ainsi que des règles liées au versement et à la destruction des documents administratifs.  Se rapprocher du service d\'archivage compétent, ainsi que des archives départementales pour un accompagnement</li>     <li>Appliquer les principes de l\'archivage intermédiaire et définitif à vos données numériques (par exemple via un Système d\'Archivage Électronique (SAE))</li>     <li>Refondre l\'arborescence des espaces de stockage afin d\'en optimiser la gestion (réduction des doublons, meilleure gestion des données et de l\'archivage, des habilitations et droits d\'accès...)</li> </ul>'),
('5e2018ad-06bd-11ee-b776-0cc47a39c2c0', 'eae87dc3-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Quelles sont les modalités de stockage et de sauvegarde de vos données informatiques (solutions logicielles, sites et applications hébergés, sauvegarde externalisée...) ? Plusieurs réponses possibles. ', 'Adopter une politique de sauvegarde adaptée aux besoins de votre structure. Celle-ci doit permettre d\'assurer la sécurité, la disponibilité des données et ainsi la continuité d\'activité en toute circonstance sans faire appel à des solutions disproportionnées (trop nombreuses redondances, durée de rétention trop longue, données non pertinentes inclues dans le processus, etc.). Se rapprocher du service compétent ou du prestataire informatique pour un accompagnement.\r\nLa bonne pratique en la matière est la règle des 3, 2, 1 :\r\n<ul>\r\n            <li>3 copies au moins des données protégées, les données primaires et deux sauvegardes</li>\r\n            <li>2 supports différents sur lesquels sont stockées ces copies ; la première sauvegarde doit se trouver sur site</li>\r\n<li>1 site externe pour la seconde sauvegarde afin de disposer d\'une ressource ultime, même si un événement catastrophique touchait le premier site</li>\r\n        </ul>', '', ''),
('5e209dec-06bd-11ee-b776-0cc47a39c2c0', 'eae8bb58-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Une politique de gestion des supports de sauvegarde (répartition des données, choix du type de support selon la nature et la disponibilité attendue, etc.) est-elle définie ? ', 'Réaffecter les données sur des supports de moins en moins énergivores (SSD, RAM, disque dur, bande magnétique, disque optique...) à mesure que la donnée est de moins en moins utilisée, selon la notion de température de la donnée (données chaudes, tièdes et froides).', '', ''),
('5e210bfc-06bd-11ee-b776-0cc47a39c2c0', 'eae8f743-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Favorisez-vous les centres de données qui prennent des engagements environnementaux ? ', 'Privilégier les prestataires qui ont ratifié le code européen de bonne conduite pour les datas centers ou encore ceux certifiés ISO 14001, ISO 26000 ou encore ISO 50001. A minima étudier les engagements pris en matière de développement durable et plus particulièrement ceux liés à l\'environnement.', 'Engagements environnementaux des centres de données', ''),
('5e21974f-06bd-11ee-b776-0cc47a39c2c0', 'eae938d8-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Si votre structure dispose d\'une ou plusieurs salles serveurs/centres de données internes : quelles en sont les modalités d\'agencement et de gestion (organisation des baies, température moyenne de fonctionnement...) ?', 'Optimiser l\'organisation et la gestion des salles serveurs/centres de données internes (organisation, architecture, etc.).', '', 'Optimiser l\'organisation et la gestion des salles serveurs/datas centers internes :   <ul>             <li>Confiner les baies des salles serveurs</li>             <li>Organiser les baies en allées chaudes et froides</li> <li>Consolider les serveurs physiques sous-utilisés pour les regrouper</li> <li>Favoriser autant que possible le free cooling</li> <li>Réutiliser l\'énergie thermique produite par le data center</li> <li>Virtualiser les serveurs physiques sous-utilisés pour les regrouper</li> <li>Mettre en place un monitoring de l\'impact de leur fonctionnement</li> <li>Privilégier les équipements conformes aux exigences ASHRAE dont les normes font référence en la matière</li>         </ul>'),
('5e21f181-06bd-11ee-b776-0cc47a39c2c0', 'eae9732c-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Quelle est la durée de vie moyenne de vos serveurs ?', 'Allonger la durée de vie des serveurs physiques par l\'adoption de pratiques numériques plus sobres.', '', ''),
('5e224bd1-06bd-11ee-b776-0cc47a39c2c0', 'eae9ad81-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Connaissez-vous la proportion de serveurs physiques et virtuels (aussi appelés Virtual machine (VM)) voire le taux de virtualisation de votre structure ?', 'Plutôt que la mise en place d\'un nouveau serveur physique, envisager la consolidation et notamment la virtualisation. La création d\'un serveur virtuel ou Virtual Machine (VM) permet d\'éviter l\'achat de nouveaux équipements et impacts liés au long de leur cycle de vie (fabrication, utilisation, fin de vie), voire le besoin de nouveaux locaux et coûts induits, mais aussi d\'augmenter le taux d\'occupation des serveurs existants qui ont tendance à être sous-utilisés ou encore de simplifier l\'infrastructure, son adaptation et sa maintenance. Il convient toutefois en premier lieu le besoin de mettre en place un nouveau serveur et de ne pas surdimensionner l\'infrastructure au regard des besoins réels de votre structure. \r\nSe rapprocher du service compétent ou du prestataire pour un accompagnement. ', 'Virtualisation des serveurs', ''),
('5e22ab8f-06bd-11ee-b776-0cc47a39c2c0', 'eae9e800-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Quelle est la capacité de stockage/utilisateur de votre structure (tous supports confondus) ? ', 'S\'assurer que la capacité de stockage/utilisateur est proportionnée aux besoins et réduire cette capacité au strict nécessaire. Veiller à appliquer ce principe aux applicatifs et notamment aux boîtes de messagerie également. \r\nHors cas de mutualisation des outils mis à disposition pour les usages professionnels et personnels, ne pas favoriser le stockage de documents numériques personnels sur les supports et lieux de stockages mis à disposition. A minima, inviter les utilisateurs à limiter cette pratique. ', '', ''),
('5e2307bd-06bd-11ee-b776-0cc47a39c2c0', 'eaea20ae-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Selon quelles modalités est-il possible de partager des documents en interne et à l\'externe ? Plusieurs réponses possibles.', 'Mettre en place des dossiers de partage de documents afin de réduire les envois de documents par mail. Des outils de travail collaboratif peuvent également être envisagés (intranet notamment). Les utilisateurs doivent être invités à privilégier l\'utilisation de ces solutions à l\'envoi d\'un email autant que possible, notamment via la charte informatique lorsqu\'elle existe.', '', ''),
('5e2355b3-06bd-11ee-b776-0cc47a39c2c0', 'eaea5d42-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Assurez-vous un suivi de la volumétrie des données numériques traitées via votre système d\'information (SI) ? ', 'Assurer un suivi de la volumétrie des données numériques traitées via votre système d\'information (SI).', 'Suivi de le volumétrie des données numériques', ''),
('5e23c64a-06bd-11ee-b776-0cc47a39c2c0', 'eaea942d-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Des obligations et/ou bonnes pratiques favorisant la sobriété numérique (gestion et tri des boîtes de messagerie, espaces de stockage en ligne, mise en veille et extinction des outils numériques...) ont-elles été mises en place via la charte informatique ou tout autre support ou format ? ', 'Intégrer les enjeux et bonnes pratiques de la sobriété numérique à la charte informatique de votre structure si elle existe. À défaut, les diffuser via un document dédié à faire signer par les utilisateurs pour en assurer l\'opposabilité.', 'Charte informatique et sobriété numérique', ''),
('5e242297-06bd-11ee-b776-0cc47a39c2c0', 'eaead655-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Votre structure fait-elle un usage régulier de la visioconférence ? ', 'Évaluer la pertinence d\'organiser une visioconférence. Si elle permet parfois d\'éviter des déplacements superflus et impactants pour l\'environnement, il est parfois préférable d\'opter pour un format en présentiel ou une conférence téléphonique selon les besoins.', '', ''),
('5e2474eb-06bd-11ee-b776-0cc47a39c2c0', 'eaeb0f2f-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Le télétravail est-il en place ? ', 'Étudier la pertinence de déployer le télétravail au sein de votre structure.\n', 'Mise en place du télétravail', ''),
('5e24dd53-06bd-11ee-b776-0cc47a39c2c0', 'eaeb4f85-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Avez-vous mis en place des consignes particulières favorisant la sobriété numérique en matière d\'impression de documents (police imposée, nombre limité d\'impressions...) ? ', 'Inviter les utilisateurs à adopter les principes de sobriété numérique en matière d\'impression (quotas, suivi des impressions, paramétrages, etc...).', 'Bonnes pratiques pour les impressions', 'Inviter les utilisateurs à adopter les principes de sobriété numérique en matière d\'impression :  - Inviter les utilisateurs à réduire leurs impressions au strict nécessaire (notamment les emails qui n\'ont, en principe, pas vocation à être imprimés). Dans de nombreux cas, l\'enregistrement au format PDF peut pallier le besoin d\'imprimer.  - L\'instauration d\'un quota d\'impressions, ou encore la mise en place de l\'impression protégée sont de nature à favoriser cette réduction.  - Lorsque l\'impression est nécessaire, réduire le contenu imprimé au strict nécessaire (sélectionner uniquement le contenu utile, ne pas imprimer les pages vides, effacer les pubs, éléments d\'interface des pages web, signatures email, images non porteuses d\'information et autres éléments non pertinents). A noter que des applications permettant d\'épurer le document avant impression existent.  - Opter pour l\'impression recto/verso en noir et blanc sauf besoin particulier.  - La réduction de la taille des caractères, le choix d\'une police de caractère adéquate (voir la recommandation dédiée), ainsi que de la largeur des marges peuvent être source d\'économies d\'encre et de papier.  - Privilégier un format standard (A4, A5...).  - Pour optimiser le résultat, utiliser la fonction \"aperçu avant impression\".  - En complément, le recours au mode \"brouillon\".'),
('5e252e66-06bd-11ee-b776-0cc47a39c2c0', 'eaeb8dc2-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'La collecte et le recyclage du papier sont-ils réalisés au sein de votre structure ? ', 'Assurer la collecte et le recyclage du papier. \nInviter les personnes à ne pas froisser le papier destiné au recyclage afin de ne pas entraver le bon déroulement de ce processus. \nLes documents papiers contenant des données personnelles doivent être passés au destructeur de documents afin d\'en préserver la confidentialité.', 'Collecte du papier', NULL),
('5e25aac6-06bd-11ee-b776-0cc47a39c2c0', 'eaebdb76-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Les services numériques (logiciels, applications...) utilisés sont-ils écoconçus ? ', 'Conformément aux dispositions de la loi AGEC, favoriser les services numériques (logiciels, applications...) écoconçus.\n\n', '', 'Favoriser les solutions logicielles et applications écoconçues.   Cf. l\'alinéa 2 de l\'article 55 de la loi AGEC : Lorsque le bien acquis est un logiciel, les administrations mentionnées au premier alinéa de l\'article L. 300-2 du code des relations entre le public et l\'administration promeuvent le recours à des logiciels dont la conception permet de limiter la consommation énergétique associée à leur utilisation.'),
('5e26131f-06bd-11ee-b776-0cc47a39c2c0', 'eaec1930-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Vos services de communication au public en ligne (principalement sites internet et applications mobiles) sont-ils écoconçus ?', 'Appliquer les principes de l\'écoconception aux sites internet, applications mobiles et autres services de communication au public en ligne développés en interne ou par le biais de prestataires externes.', '', ''),
('5e26593f-06bd-11ee-b776-0cc47a39c2c0', 'eaec7d75-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Un suivi statistiques et/ou le dépôt de cookies et autres traceurs sont-ils appliqués aux services de communication au public en ligne (principalement sites internet et applications mobiles) de votre structure ? ', 'Supprimer les cookies et autres traceurs dont les fonctionnalités ne sont pas exploitées.\r\nDans le cas où de tels outils sont utilisés, privilégier ceux qui collectent un minimum de données.\r\nSe rapprocher du service interne et/ou du prestataire informatique compétent(s).', '', ''),
('5e26b458-06bd-11ee-b776-0cc47a39c2c0', 'eaecba23-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Les personnes en charge de la communication sont-elles au fait des principes de la sobriété éditoriale ? ', 'Tenir compte des principes de la sobriété éditoriale dans le cadre de la production des supports et la politique de communication de la structure.', '', 'Tenir compte des principes de la sobriété éditoriale dans le cadre de la production des supports de communication de la structure :  <ul> <li>Choisir le format le plus adapté pour la communication envisagée (papier ou numérique : si une information a une durée de vie courte, il est préférable de communiquer au format numérique)</li> <li>Adapter la taille et format des images et les utiliser avec parcimonie</li> <li>Ne pas multiplier les contenus vidéo et prêter attention à la méthode de diffusion (préférer par exemple une image-lien renvoyant vers la plateforme-tierce de diffusion que d\'insérer un lecteur média sur le site, prévoir une retranscription textuelle ou un résumé afin qu\'elle ne soit pas lancée inutilement, trouver la résolution optimale : la plus faible possible sans altérer la bonne transmission d\'information...)</li> <li>Pour les documents à télécharger : opter pour le format le plus adapté et le plus léger (le format PDF est réputé plus léger, ce qui n\'est pas toujours le cas de ceux produits via des logiciels de graphisme ; Ce format pose toutefois des difficultés en termes d\'accessibilité numérique). Les logiciels de suite bureautique prévoient à cet effet des options visant à réduire le poids des fichiers qu\'il convient d\'utiliser. A noter cependant qu\'un contenu au format HTML (directement intégré au site) reste plus léger qu\'un fichier en téléchargement</li> <li>Cibler au mieux les destinataires afin de maximiser le taux de lecture et ainsi prévenir les envois qui ne seront pas lus</li> <li>Rédiger le message de façon claire et simple en évitant les contenus superflus</li> <li>Appliquer les bonnes pratiques en matière d\'impression (éviter les aplats de couleurs et l\'utilisation du pelliculage ou du vernissage, opter pour des couleurs composées à partir d\'une ou plusieurs couleurs de base de la quadrichromie et éviter les couleurs à effet métallique qui nécessitent l\'emploi d\'encres auxquelles sont ajoutées des métaux notamment ou encore choisir un papier écolabellisé et/ou recyclé)</li> <li>Favoriser les pliages et découpages ainsi que les colles végétales à base d\'eau. Eviter en revanche les matériaux susceptibles de gêner le recyclage (agrafes, spirales...)</li> <li>Rédiger le contenu de manière à ce qu\'il ne se périme pas rapidement</li>         </ul>'),
('5e26ffc6-06bd-11ee-b776-0cc47a39c2c0', 'eaecfa36-06bc-11ee-b776-0cc47a39c2c0', 0, 4, 'Avez-vous imposé des règles particulières en matière de traitement de texte et autres documents bureautiques (police d\'écriture, tailles et couleurs des caractères, marges, format de documents (Word, PDF, etc.), etc.) ? ', 'Mettre en place des règles favorisant la sobriété numérique dans l\'utilisation des suites bureautiques via la charte informatique ou encore sous forme de charte graphique.', 'Documents bureautiques', ''),
('5e274443-06bd-11ee-b776-0cc47a39c2c0', 'eaed3454-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Votre structure dispose-t-elle d\'une charte graphique ? ', 'Concevoir une charte graphique tenant compte des principes de la sobriété numérique (choix de la police, éviter les aplats de couleurs...).', '', ''),
('5e27dd50-06bd-11ee-b776-0cc47a39c2c0', 'eaedab44-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Votre structure a-t-elle adopté un schéma de promotion des achats publics socialement et écologiquement responsables ?', 'Adopter un schéma de promotion des achats publics socialement et écologiquement responsables, conformément aux dispositions de l\'article L2111-3 du code de la Commande publique.\nVeiller à inclure des objectifs environnementaux pour les achats numériques.', '', 'Conformément aux dispositions de l\'article L2111-3 du code de la Commande publique : « Les collectivités territoriales et les acheteurs soumis au présent code dont le statut est fixé par la loi adoptent un schéma de promotion des achats publics socialement et écologiquement responsables lorsque le montant total annuel de leurs achats est supérieur à [à cent millions d\'euros hors taxes.].  Ce schéma, rendu public, détermine les objectifs de politique d\'achat comportant des éléments à caractère social visant à concourir à l\'intégration sociale et professionnelle de travailleurs handicapés ou défavorisés et des éléments à caractère écologique ainsi que les modalités de mise en œuvre et de suivi annuel de ces objectifs. Ce schéma contribue également à la promotion d\'une économie circulaire. » Veiller à inclure des objectifs environnementaux pour les achats numériques.  À noter que, à compter du 1er janvier 2023, suite à l\'adoption de la loi Climat et résilience, le SPASER doit être rendu public notamment via le site internet de la structure, s\'il existe.  Des précisions seront également ajoutées concernant la rédaction du document : « Ce schéma comporte des indicateurs précis, exprimés en nombre de contrats ou en valeur et publiés tous les deux ans, sur les taux réels d\'achats publics relevant des catégories de l\'achat socialement et écologiquement responsable parmi les achats publics réalisés par la collectivité ou l\'acheteur concerné. Il précise les objectifs cibles à atteindre pour chacune de ces catégories, notamment ceux relatifs aux achats réalisés auprès des entreprises solidaires d\'utilité sociale agréées au sens de l\'article L. 3332-17-1 du code du travail, d\'une part, ou auprès des entreprises employant des personnes défavorisées ou appartenant à des groupes vulnérables, d\'autre part. ». '),
('5e282bc3-06bd-11ee-b776-0cc47a39c2c0', 'eaede4b2-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Des clauses sociales sont-elles inclues dans les appels d\'offre et contrats conclus hors marché ? ', 'Intégrer des clauses sociales dans les appels d\'offre et contrats conclus hors marché. \r\nA noter que des dispositions concernant les marchés publics doivent entrer en vigueur sur à l\'adoption de la loi Climat et résilience, suivant une date fixée par un décret en cours d\'étude et au plus tard le 22 août 2026. Celles-ci viendront généraliser la prise en compte de considérations relatives au domaine social ou l\'emploi en la matière, que ce soit dans les spécifications techniques que les conditions d\'exécution.', 'Clauses sociales', ''),
('5e287524-06bd-11ee-b776-0cc47a39c2c0', 'eaee2338-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Tenez-vous compte du Débit d\'Absorption Spécifique (DAS) dans le cadre des achats numériques ? ', 'Fixer un niveau de DAS maximum dans le cadre de l\'acquisition d\'équipements numériques.\r\nEn complément, diffuser les bonnes pratiques suivantes aux utilisateurs : \r\n<ul>\r\n            <li>Éviter de placer l\'appareil contre le cœur, les hanches, les aisselles ou les parties génitales</li>\r\n            <li>Pour les téléphones, éviter les communications prolongées à l\'oreille en utilisant le haut parleur ou un kit main libre filaire</li>\r\n<li>Éloigner dès que possible l\'appareil du corps</li>\r\n<li>Dans la mesure du possible, privilégier les lieux où le signal réseau est bon</li>\r\n<li>Éviter de dormir avec le téléphone à moins de 50 cm de la tête, en charge ou non (le mettre en mode avion ou l\'éteindre)</li>\r\n        </ul>\r\n\r\nConsulter les notices des appareils pour connaître les conditions d\'usage fixées par leur fabricant. ', '', ''),
('5e28fe0e-06bd-11ee-b776-0cc47a39c2c0', 'eaee9d7f-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Votre structure mène-t-elle une démarche de mise en conformité aux règles relatives à la protection des données (Règlement Général sur la Protection des Données (RGPD), Loi Informatique et Libertés (LIL)...) ? ', 'Commencer ou poursuivre la mise en conformité de la structure aux règles relatives à la protection des données, à commencer par le RGPD (Règlement Général sur la Protection des Données) et la LIL (Loi Informatique et Libertés).', '', ''),
('5e295408-06bd-11ee-b776-0cc47a39c2c0', 'eaeed982-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Des actions de sensibilisation sont-elles menées auprès du personnel sur les enjeux et bonnes pratiques en matière de protection des données et de sécurité informatique ? ', 'Assurer une sensibilisation régulière des agents et autres personnels de votre structure, aux enjeux et bonnes pratiques de protection des données et de sécurité informatique.\r\nEn complément de sessions de sensibilisation, diffuser ces enjeux en interne via différents supports physiques et numériques (note d\'organisation, affichage, lettre d\'information interne...).', 'Sensibilisation des agents et autres personnels', ''),
('5e29a826-06bd-11ee-b776-0cc47a39c2c0', 'eaef0f77-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Des actions de sensibilisation sont-elles menées auprès des élus sur les enjeux et bonnes pratiques en matière de protection des données et de sécurité informatique ? ', 'Assurer une sensibilisation régulière des élus et membres des instances dirigeantes de votre structure, aux enjeux et bonnes pratiques de protection des données et de sécurité informatique. ', 'Sensibilisation des élus et membres des instances dirigeantes', ''),
('5e29e7fe-06bd-11ee-b776-0cc47a39c2c0', 'eaef4a05-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Une politique de protection contre les risques cyber a-t-elle été adoptée pour votre structure ? ', 'Assurer la sécurisation du système d\'information contre les menaces cyber. ', '', ''),
('5e2a26cd-06bd-11ee-b776-0cc47a39c2c0', 'eaef89eb-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Avez-vous réalisé l\'homologation au Référentiel Général de Sécurité (RGS) de votre système d\'information (SI) ? ', 'Réaliser l\'homologation RGS de votre système d\'information. ', 'Homologation RGS', ''),
('5e2a6990-06bd-11ee-b776-0cc47a39c2c0', 'eaefc832-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Votre structure a-t-elle mis en place une démarche en faveur de l\'inclusion numérique ? ', 'Adopter une démarche favorisant l\'inclusion numérique (aide à la réalisation de démarches en ligne, à l\'accès aux outils numériques, organisation d\'ateliers multimédias formant aux usages du numériques...).', '', ''),
('5e2ab4e0-06bd-11ee-b776-0cc47a39c2c0', 'eaf00a4e-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Des actions de sensibilisation sont-elles menées auprès du personnel sur les enjeux et bonnes pratiques en matière d\'inclusion numérique ? ', 'Assurer une sensibilisation régulière des agents et autres personnels de votre structure, aux enjeux et bonnes pratiques en matière d\'inclusion numérique.\r\nEn complément de sessions de sensibilisation, diffuser ces enjeux en interne via différents supports physiques et numériques (note d\'organisation, affichage, lettre d\'information interne...).', 'Sensibilisation des agents et autres personnels', ''),
('5e2af979-06bd-11ee-b776-0cc47a39c2c0', 'eaf0418a-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Des actions de sensibilisation sont-elles menées auprès des élus sur les enjeux et bonnes pratiques en matière de protection d\'inclusion numérique ? ', 'Assurer une sensibilisation régulière des élus et membres des instances dirigeantes de votre structure, aux enjeux et bonnes pratiques en matière d\'inclusion numérique. ', 'Sensibilisation des élus et membres des instances dirigeantes', ''),
('5e2b59fb-06bd-11ee-b776-0cc47a39c2c0', 'eaf0788d-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Votre structure respecte-t-elle les préconisations et obligations en matière d\'accessibilité numérique ? ', 'Respecter les obligations et bonnes pratiques en matière d\'accessibilité numérique, à commencer par le RGAA (Référentiel Général d\'Amélioration de l\'Accessibilité).', '', ''),
('5e2bcda7-06bd-11ee-b776-0cc47a39c2c0', 'eaf0bf23-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Votre structure respecte-t-elle les préconisations et obligations en matière d\'ouverture de ses données (Open Data ) ? ', 'Respecter les obligations et bonnes pratiques en matière d\'ouverture des données, notamment pour les collectivités de plus de 3500 habitants et comptant au moins 50 agents.', '', ''),
('5e2c1c1c-06bd-11ee-b776-0cc47a39c2c0', 'eaf0fe3d-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Mettez -vous à disposition du public des bornes d\'accès/une connexion Wifi gratuite ? ', 'Mettre à disposition du public des points de connexion Wifi en libre accès.', '', ''),
('5e2c687f-06bd-11ee-b776-0cc47a39c2c0', 'eaf1cc7a-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Souhaitez-vous diffuser les enjeux et bonnes pratiques du numérique responsable auprès du public ? ', 'Sensibiliser et diffuser les enjeux et bonnes pratiques du numérique responsable auprès des administrés et acteurs locaux. ', '', ''),
('cdca3837-4c96-11ee-b615-0cc47a39c2c2', 'ead9ef35-06bc-11ee-b776-0cc47a39c2c0', 2, 4, 'Votre structure a-t-elle engagé des actions ou fixé des objectifs en matière de sobriété numérique ?', 'Engager des actions en matière de sobriété numérique.', 'Actions engagées et objectifs fixés', NULL),
('ddcddb7c-467c-11ee-b615-0cc47a39c2c2', 'eaee6416-06bc-11ee-b776-0cc47a39c2c0', 1, 4, 'Faites-vous appel à des acteurs locaux de la réparation, du réemploi et/ou de la réutilisation d\'équipements informatiques ?', 'Il existe des filières locales oeuvrant pour l\'économie circulaire (réparation et/ou revente d\'équipements numériques en fin d\'usage) regroupant notamment des acteurs de l\'économie sociale et solidaire.', 'Acteurs locaux', ''),
('f582428a-4af9-11ee-b615-0cc47a39c2c2', 'fd893fe8-4af6-11ee-b615-0cc47a39c2c2', 2, 4, 'Combien d’imprimantes/copieurs sont-ils mis à disposition des utilisateurs et quelles sont les modalités de répartitions ?', 'Optimiser l\'utilisation du parc d\'impression (modalités de répartition, choix, paramétrage et maintenance du matériel, sensibilisation des utilisateurs, etc.).', 'Optimisation du parc d\'impression', 'Optimiser l\'utilisation du parc d\'impression :\n- Supprimer les imprimantes individuelles au profit des copieurs multifonction mutualisés ; \n- Faire une étude des besoins afin de définir le type, les fonctionnalités, le nombre d\'imprimantes nécessaires et leur affectation optimale au sein des services ;\n- Opter pour des imprimantes robustes et éco-conçues ;\n- Procéder au paramétrage des impressions (voir la recommandation dédiée) ; \n- Suivre la consommation énergétique du parc (par exemple via une solution logicielle) ; \n- Dans la mesure du possible, débrancher les imprimantes (sous réserve de fonctionnalités liées au redémarrage qui pourraient entrainer des surconsommations comme le nettoyage des têtes d\'impression) ou mettre en place une solution de gestion des consommations durant les temps de veille/arrêts prolongés (nuits et week-ends principalement) ; \n- Former les utilisateurs à l\'utilisation des imprimantes pour réduire les erreurs d\'impression (un guide d\'utilisation peut être mis à leur disposition voire affiché à proximité par exemple) ; \n- Sensibiliser les utilisateurs aux impacts des impressions (environnementaux, financiers...) et aux gestes clés de l\'impression écoresponsable ; \n- Favoriser la dématérialisation pour réduire les besoins.');
